/* DAWAH X — ahmad, অধ্যায় 88 · খণ্ড 88 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][88]=[[17401,17401,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏سَمِعَ ‏ ‏زِرَّ بْنَ حُبَيْشٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏صَفْوَانَ بْنَ عَسَّالٍ الْمُرَادِيَّ ‏ ‏فَقَالَ مَا جَاءَ بِكَ فَقُلْتُ ‏ ‏ابْتِغَاءَ ‏ ‏الْعِلْمِ قَالَ فَإِنَّ الْمَلَائِكَةَ تَضَعُ أَجْنِحَتَهَا لِطَالِبِ الْعِلْمِ رِضًا بِمَا يَطْلُبُ قُلْتُ ‏ ‏حَكَّ ‏ ‏فِي نَفْسِي مَسْحٌ عَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أَوْ فِي صَدْرِي ‏ ‏بَعْدَ ‏ ‏الْغَائِطِ ‏ ‏وَالْبَوْلِ وَكُنْتَ امْرَأً مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُكَ أَسْأَلُكَ هَلْ سَمِعْتَ مِنْهُ فِي ذَلِكَ شَيْئًا قَالَ نَعَمْ كَانَ يَأْمُرُنَا ‏ ‏إِذَا كُنَّا سَفَرًا ‏ ‏أَوْ مُسَافِرِينَ ‏ ‏أَنْ لَا نَنْزِعَ ‏ ‏خِفَافَنَا ‏ ‏ثَلَاثَةَ أَيَّامٍ وَلَيَالِيهِنَّ إِلَّا مِنْ ‏ ‏جَنَابَةٍ ‏ ‏وَلَكِنْ مِنْ ‏ ‏غَائِطٍ ‏ ‏وَبَوْلٍ وَنَوْمٍ قَالَ قُلْتُ لَهُ هَلْ سَمِعْتَهُ يَذْكُرُ الْهَوَى قَالَ نَعَمْ بَيْنَمَا نَحْنُ مَعَهُ فِي مَسِيرَةٍ إِذْ نَادَاهُ أَعْرَابِيٌّ بِصَوْتٍ ‏ ‏جَهْوَرِيٍّ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏فَقُلْنَا ‏ ‏وَيْحَكَ ‏ ‏اغْضُضْ ‏ ‏مِنْ صَوْتِكَ فَإِنَّكَ قَدْ نُهِيتَ عَنْ ذَلِكَ فَقَالَ وَاللَّهِ لَا ‏ ‏أَغْضُضُ ‏ ‏مِنْ صَوْتِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَاءَ ‏ ‏وَأَجَابَهُ عَلَى نَحْوٍ مِنْ مَسْأَلَتِهِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً وَأَجَابَهُ نَحْوًا مِمَّا تَكَلَّمَ بِهِ ‏ ‏فَقَالَ أَرَأَيْتَ رَجُلًا أَحَبَّ قَوْمًا وَلَمَّا يَلْحَقْ بِهِمْ قَالَ هُوَ مَعَ مَنْ أَحَبَّ قَالَ ثُمَّ لَمْ يَزَلْ يُحَدِّثُنَا حَتَّى قَالَ إِنَّ مِنْ قِبَلِ الْمَغْرِبِ لَبَابًا مَسِيرَةُ عَرْضِهِ سَبْعُونَ ‏ ‏أَوْ أَرْبَعُونَ ‏ ‏عَامًا فَتَحَهُ اللَّهُ عَزَّ وَجَلَّ لِلتَّوْبَةِ يَوْمَ خَلَقَ السَّمَوَاتِ وَالْأَرْضَ وَلَا يُغْلِقُهُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْهُ ‏","","",""],[17402,17402,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏لِآخَرَ انْطَلِقْ بِنَا إِلَى هَذَا النَّبِيِّ قَالَ لَا تَقُلْ هَذَا فَإِنَّهُ لَوْ سَمِعَهَا كَانَ لَهُ أَرْبَعُ أَعْيُنٍ قَالَ فَانْطَلَقْنَا إِلَيْهِ فَسَأَلْنَاهُ عَنْ هَذِهِ الْآيَةِ ‏ { ‏وَلَقَدْ آتَيْنَا ‏ ‏مُوسَى ‏ ‏تِسْعَ آيَاتٍ بَيِّنَاتٍ ‏} ‏قَالَ ‏ ‏لَا تُشْرِكُوا بِاللَّهِ شَيْئًا وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا تَسْرِقُوا وَلَا تَزْنُوا وَلَا تَفِرُّوا مِنْ ‏ ‏الزَّحْفِ ‏ ‏وَلَا تَسْحَرُوا وَلَا تَأْكُلُوا الرِّبَا وَلَا تُدْلُوا بِبَرِيءٍ إِلَى ذِي سُلْطَانٍ لِيَقْتُلَهُ وَعَلَيْكُمْ خَاصَّةً ‏ ‏يَهُودُ ‏ ‏أَنْ لَا تَعْتَدُوا فِي السَّبْتِ فَقَالَا نَشْهَدُ إِنَّكَ رَسُولُ اللَّهِ ‏","","",""],[17403,17403,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رَوْقٍ عَطِيَّةُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْغَرِيفِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَبُو الْغَرِيفِ عَبْدُ اللَّهِ بْنُ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ الْمُرَادِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَقَالَ ‏ ‏اغْزُوا بِسْمِ اللَّهِ فِي سَبِيلِ اللَّهِ وَلَا ‏ ‏تَغُلُّوا ‏ ‏وَلَا ‏ ‏تَغْدِرُوا ‏ ‏وَلَا ‏ ‏تُمَثِّلُوا ‏ ‏وَلَا تَقْتُلُوا وَلِيدًا لِلْمُسَافِرِ ثَلَاثٌ مَسْحٌ عَلَى الْخُفَّيْنِ وَلِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17404,17404,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا لِطَالِبِ الْعِلْمِ رِضًا بِمَا طَلَبَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏أَبِي رَوْقٍ عَطِيَّةَ بْنِ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏يُونُسَ ‏","","",""],[17405,17405,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏صَفْوَانَ بْنَ عَسَّالٍ الْمُرَادِيَّ ‏ ‏فَقَالَ مَا جَاءَ بِكَ فَقُلْتُ ابْتِغَاءُ الْعِلْمِ فَقَالَ لَقَدْ بَلَغَنِي أَنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا لِطَالِبِ الْعِلْمِ رِضًا بِمَا يَفْعَلُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ قَالَ فَمَا ‏ ‏بَرِحَ ‏ ‏يُحَدِّثُنِي حَتَّى حَدَّثَنِي أَنَّ اللَّهَ عَزَّ وَجَلَّ جَعَلَ بِالْمَغْرِبِ بَابًا مَسِيرَةُ عَرْضِهِ سَبْعُونَ عَامًا لِلتَّوْبَةِ لَا يُغْلَقُ مَا لَمْ تَطْلُعْ الشَّمْسُ مِنْ قِبَلِهِ وَذَلِكَ قَوْلُ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا ‏}","","",""],[17406,17406,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏وَنَحْنُ مُحْرِمُونَ وَقَدْ حَصَرَنَا الْمُشْرِكُونَ وَكَانَتْ لِي ‏ ‏وَفْرَةٌ ‏ ‏فَجَعَلَتْ ‏ ‏الْهَوَامُّ ‏ ‏تَسَّاقَطُ عَلَى وَجْهِي فَمَرَّ بِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيُؤْذِيكَ ‏ ‏هَوَامُّ ‏ ‏رَأْسِكَ قُلْتُ نَعَمْ فَأَمَرَهُ أَنْ يَحْلِقَ قَالَ وَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ ‏ ‏صَدَقَةٍ ‏ ‏أَوْ ‏ ‏نُسُكٍ ‏ }","","",""],[17407,17407,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏قَمِلْتُ ‏ ‏حَتَّى ظَنَنْتُ أَنَّ كُلَّ شَعْرَةٍ مِنْ رَأْسِي فِيهَا الْقَمْلُ مِنْ أَصْلِهَا إِلَى فَرْعِهَا فَأَمَرَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ رَأَى ذَلِكَ قَالَ ‏ ‏احْلِقْ وَنَزَلَتْ الْآيَةُ قَالَ أَطْعِمْ سِتَّةَ مَسَاكِينَ ثَلَاثَةَ ‏ ‏آصُعٍ ‏ ‏مِنْ تَمْرٍ ‏","","",""],[17408,17408,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِسْحَاقَ بْنِ فُلَانِ بْنِ كَعْبِ بْنِ عُجْرَةَ ‏ ‏أَنَّ ‏ ‏أَبَا ثُمَامَةَ الْحَنَّاطَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏كَعْبَ بْنَ عُجْرَةَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ فَأَحْسَنَ وُضُوءَهُ ثُمَّ خَرَجَ عَامِدًا إِلَى الصَّلَاةِ فَلَا يُشَبِّكْ بَيْنَ يَدَيْهِ فَإِنَّهُ فِي الصَّلَاةِ ‏","","",""],[17409,17409,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ قَدْ عَلِمْنَا السَّلَامَ عَلَيْكَ فَكَيْفَ الصَّلَاةُ عَلَيْكَ قَالَ قُولُوا ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ اللَّهُمَّ بَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ ‏","","",""],[17410,17410,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏وحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏لَقِيَنِي ‏ ‏كَعْبُ بْنُ عُجْرَةَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏أَلَا أُهْدِي لَكَ هَدِيَّةً خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ قَدْ عَلِمْنَا ‏ ‏أَوْ عَرَفْنَا ‏ ‏كَيْفَ السَّلَامُ عَلَيْكَ فَكَيْفَ الصَّلَاةُ قَالَ قُولُوا ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ اللَّهُمَّ بَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ ‏","","",""],[17411,17411,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ بْنِ مَالِكٍ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَذَاهُ الْقَمْلُ فِي رَأْسِهِ ‏ ‏فَأَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَحْلِقَ رَأْسَهُ وَقَالَ صُمْ ثَلَاثَةَ أَيَّامٍ أَوْ أَطْعِمْ سِتَّةَ مَسَاكِينَ ‏ ‏مُدَّيْنِ ‏ ‏مُدَّيْنِ ‏ ‏لِكُلِّ إِنْسَانٍ أَوْ ‏ ‏انْسُكْ ‏ ‏بِشَاةٍ أَيَّ ذَلِكَ فَعَلْتَ أَجْزَأَكَ ‏","","",""],[17412,17412,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أُوقِدُ تَحْتَ ‏ ‏قِدْرٍ ‏ ‏وَالْقَمْلُ يَتَنَاثَرُ عَلَى وَجْهِي ‏ ‏أَوْ قَالَ عَلَى حَاجِبَيَّ ‏ ‏فَقَالَ أَيُؤْذِيكَ ‏ ‏هَوَامُّ ‏ ‏رَأْسِكَ قَالَ قُلْتُ نَعَمْ قَالَ ‏ ‏فَاحْلِقْهُ وَصُمْ ثَلَاثَةَ أَيَّامٍ أَوْ أَطْعِمْ سِتَّةَ مَسَاكِينَ أَوْ ‏ ‏انْسُكْ ‏ ‏نَسِيكَةً ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏لَا أَدْرِي بِأَيَّتِهِنَّ بَدَأَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏الْحَكَمُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏لَقِيَنِي ‏ ‏كَعْبُ بْنُ عُجْرَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17413,17413,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ ‏ ‏قَالَ ‏ ‏قَعَدْتُ إِلَى ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ فَسَأَلْتُهُ عَنْ هَذِهِ الْآيَةِ ‏ { ‏فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ ‏ ‏صَدَقَةٍ ‏ ‏أَوْ ‏ ‏نُسُكٍ ‏ } ‏قَالَ فَقَالَ ‏ ‏كَعْبٌ ‏ ‏نَزَلَتْ فِيَّ كَانَ بِي ‏ ‏أَذًى ‏ ‏مِنْ رَأْسِي فَحُمِلْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْقَمْلُ يَتَنَاثَرُ عَلَى وَجْهِي فَقَالَ مَا كُنْتُ أَرَى أَنَّ ‏ ‏الْجَهْدَ ‏ ‏بَلَغَ بِكَ مَا أَرَى أَتَجِدُ شَاةً فَقُلْتُ لَا فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ ‏ ‏صَدَقَةٍ ‏ ‏أَوْ ‏ ‏نُسُكٍ ‏ } ‏قَالَ صَوْمُ ثَلَاثَةِ أَيَّامٍ أَوْ إِطْعَامُ سِتَّةِ مَسَاكِينَ نِصْفَ ‏ ‏صَاعِ ‏ ‏طَعَامٍ لِكُلِّ مِسْكِينٍ قَالَ فَنَزَلَتْ فِيَّ خَاصَّةً وَهِيَ لَكُمْ عَامَّةً ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَصْبَهَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَعْقِلٍ ‏ ‏يَقُولُ ‏ ‏قَعَدْتُ إِلَى ‏ ‏كَعْبٍ ‏ ‏فِي هَذَا الْمَسْجِدِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَصْبَهَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَعْقِلٍ ‏ ‏قَالَ ‏ ‏قَعَدْتُ إِلَى ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏فِي هَذَا الْمَسْجِدِ فَسَأَلْتُهُ عَنْ هَذِهِ الْآيَةِ فَذَكَرَ الْحَدِيثَ وَقَالَ أَطْعِمْ سِتَّةَ مَسَاكِينَ كُلَّ مِسْكِينٍ نِصْفَ ‏ ‏صَاعٍ ‏ ‏مِنْ طَعَامٍ ‏","","",""],[17414,17414,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَتَطَهَّرُ رَجُلٌ فِي بَيْتِهِ ثُمَّ يَخْرُجُ لَا يُرِيدُ إِلَّا الصَّلَاةَ إِلَّا كَانَ فِي صَلَاةٍ حَتَّى يَقْضِيَ صَلَاتَهُ وَلَا يُخَالِفْ أَحَدُكُمْ بَيْنَ أَصَابِعِ يَدَيْهِ فِي الصَّلَاةِ ‏","","",""],[17415,17415,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏رَآنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَمْلِي يَتَسَاقَطُ عَلَى وَجْهِي فَقَالَ ‏ ‏أَتُؤْذِيكَ ‏ ‏هَوَامُّكَ ‏ ‏هَذِهِ قَالَ قُلْتُ نَعَمْ قَالَ ‏ ‏فَأَمَرَنِي أَنْ أَحْلِقَ وَهُمْ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏وَلَمْ يُبَيِّنْ لَهُمْ أَنَّهُمْ يَحْلِقُونَ بِهَا وَهُمْ عَلَى طَمَعٍ أَنْ يَدْخُلُوا ‏ ‏مَكَّةَ ‏ ‏فَأَنْزَلَ اللَّهُ الْفِدْيَةَ فَأَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُطْعِمَ فِرْقًا بَيْنَ سِتَّةِ مَسَاكِينَ أَوْ أَصُومَ ثَلَاثَةَ أَيَّامٍ أَوْ أَذْبَحَ شَاةً ‏","","",""],[17416,17416,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏بَعْضِ ‏ ‏بَنِي كَعْبِ بْنِ عُجْرَةَ ‏ ‏عَنْ ‏ ‏كَعْبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأْتَ فَأَحْسَنْتَ وُضُوءَكَ ثُمَّ ‏ ‏عَمَدْتَ ‏ ‏إِلَى الْمَسْجِدِ فَأَنْتَ فِي صَلَاةٍ فَلَا تُشَبِّكْ بَيْنَ أَصَابِعِكَ ‏","","",""],[17417,17417,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ أَبُو تَمَّامٍ الْأَسَدِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ فَأَحْسَنْتَ وُضُوءَكَ ثُمَّ خَرَجْتَ عَامِدًا إِلَى الْمَسْجِدِ فَلَا تُشَبِّكَنَّ بَيْنَ أَصَابِعِكَ ‏ ‏قَالَ ‏ ‏قُرَّانُ ‏ ‏أُرَاهُ قَالَ فَإِنَّكَ فِي صَلَاةٍ ‏","","",""],[17418,17418,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏كَعْبًا ‏ ‏أَنْ يَحْلِقَ رَأْسَهُ مِنْ الْقَمْلِ قَالَ صُمْ ثَلَاثَةَ أَيَّامٍ أَوْ أَطْعِمْ سِتَّةَ مَسَاكِينَ ‏ ‏مُدَّيْنِ ‏ ‏مُدَّيْنِ ‏ ‏أَوْ اذْبَحْ ‏","","",""],[17419,17419,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَمَنَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَأَنَا كَثِيرُ الشَّعْرِ فَقَالَ كَأَنَّ ‏ ‏هَوَامَّ ‏ ‏رَأْسِكَ ‏ ‏تُؤْذِيكَ فَقُلْتُ أَجَلْ قَالَ ‏ ‏فَاحْلِقْهُ وَاذْبَحْ شَاةً أَوْ صُمْ ثَلَاثَةَ أَيَّامٍ أَوْ تَصَدَّقْ بِثَلَاثَةِ ‏ ‏آصُعٍ مِنْ تَمْرٍ بَيْنَ سِتَّةِ مَسَاكِينَ ‏","","",""],[17420,17420,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ الرَّازِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏مُغِيرَةُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَطَرٍ الْوَرَّاقِ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِتْنَةً فَقَرَّبَهَا وَعَظَّمَهَا قَالَ ثُمَّ مَرَّ رَجُلٌ ‏ ‏مُتَقَنِّعٌ ‏ ‏فِي ‏ ‏مِلْحَفَةٍ ‏ ‏فَقَالَ هَذَا يَوْمَئِذٍ عَلَى الْحَقِّ فَانْطَلَقْتُ مُسْرِعًا ‏ ‏أَوْ قَالَ مُحْضِرًا ‏ ‏فَأَخَذْتُ ‏ ‏بِضَبْعَيْهِ ‏ ‏فَقُلْتُ هَذَا يَا رَسُولَ اللَّهِ قَالَ هَذَا فَإِذَا هُوَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[17421,17421,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلِ بْنِ مُقَرِّنٍ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ أَنْ ‏ ‏يَصُومَ ثَلَاثَةَ أَيَّامٍ أَوْ يُطْعِمَ سِتَّةَ مَسَاكِينَ أَوْ يَذْبَحَ شَاةً ‏","","",""],[17422,17422,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ قَرْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ الْمُزَنِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏كَعْبَ بْنَ عُجْرَةَ ‏ ‏يَقُولُ ‏ ‏فِي هَذَا الْمَسْجِدِ ‏ ‏يَعْنِي ‏ ‏مَسْجِدَ الْكُوفَةِ ‏ ‏فِيَّ نَزَلَتْ هَذِهِ الْآيَةُ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَلَّيْنَا بِعُمْرَةٍ فَوَقَعَ الْقَمْلُ فِي رَأْسِي وَلِحْيَتِي وَحَاجِبَيَّ وَشَارِبِي فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْسَلَ إِلَيَّ فَدَعَانِي فَلَمَّا رَآنِي قَالَ ‏ ‏لَقَدْ أَصَابَكَ بَلَاءٌ وَنَحْنُ لَا ‏ ‏نَشْعُرُ ‏ ‏ادْعُ ‏ ‏الْحَجَّامَ ‏ ‏فَلَمَّا جَاءَهُ أَمَرَهُ فَحَلَقَنِي قَالَ أَتَقْدِرُ عَلَى ‏ ‏نُسُكٍ ‏ ‏قُلْتُ لَا قَالَ فَصُمْ ثَلَاثَةَ أَيَّامٍ أَوْ أَطْعِمْ سِتَّةَ مَسَاكِينَ لِكُلِّ مِسْكِينٍ نِصْفُ ‏ ‏صَاعٍ ‏ ‏مِنْ تَمْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏نَزَلَتْ فِيَّ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏بِنَحْوٍ مِنْ ذَلِكَ إِلَّا أَنَّهُ قَالَ أَطْعِمْ الْمَسَاكِينَ ثَلَاثَةَ ‏ ‏آصُعٍ ‏ ‏مِنْ تَمْرٍ بَيْنَ سِتَّةِ مَسَاكِينَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏إِنَّ ‏ ‏كَعْبًا ‏ ‏أَحْرَمَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَاهُ وَقَالَا ثَلَاثَةُ ‏ ‏آصُعٍ ‏ ‏مِنْ تَمْرٍ بَيْنَ سِتَّةِ مَسَاكِينَ ‏","","",""],[17423,17423,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏كَعْبًا ‏ ‏حِينَ حَلَقَ رَأْسَهُ أَنْ يَذْبَحَ شَاةً أَوْ يَصُومَ ثَلَاثَةَ أَيَّامٍ أَوْ يُطْعِمَ ‏ ‏فِرْقًا ‏ ‏بَيْنَ سِتَّةِ مَسَاكِينَ ‏","","",""],[17424,17424,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو حَصِينٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْعَدَوِىِّ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ دَخَلَ وَنَحْنُ تِسْعَةٌ وَبَيْنَنَا وِسَادَةٌ مِنْ ‏ ‏أَدَمٍ ‏ ‏فَقَالَ ‏ ‏إِنَّهَا سَتَكُونُ بَعْدِي أُمَرَاءُ يَكْذِبُونَ وَيَظْلِمُونَ فَمَنْ دَخَلَ عَلَيْهِمْ فَصَدَّقَهُمْ بِكِذْبِهِمْ وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ وَلَيْسَ ‏ ‏بِوَارِدٍ ‏ ‏عَلَيَّ الْحَوْضَ وَمَنْ لَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ وَيُعِنْهُمْ عَلَى ظُلْمِهِمْ فَهُوَ مِنِّي وَأَنَا مِنْهُ وَهُوَ ‏ ‏وَارِدٌ ‏ ‏عَلَيَّ الْحَوْضَ ‏","","",""],[17425,17425,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏أَخْبَرَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا قَدْ عَلِمْنَا السَّلَامَ عَلَيْكَ فَكَيْفَ الصَّلَاةُ قَالَ فَعَلَّمَهُ أَنْ يَقُولَ ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ ‏","","",""],[17426,17426,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَيْفٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏كَعْبُ بْنُ عُجْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ عَلَيْهِ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏قَالَ وَرَأْسُهُ ‏ ‏يَتَهَافَتُ ‏ ‏قَمْلًا قَالَ أَيُؤْذِيكَ ‏ ‏هَوَامُّكَ ‏ ‏قَالَ قُلْتُ نَعَمْ قَالَ فَاحْلِقْ رَأْسَكَ قَالَ فِيَّ نَزَلَتْ ‏ { ‏فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ ‏} ‏قَالَ فَأَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏صُمْ ثَلَاثَةَ أَيَّامٍ أَوْ تَصَدَّقْ ‏ ‏بِفِرْقٍ ‏ ‏بَيْنَ سِتَّةٍ أَوْ بِنُسُكٍ مَا تَيَسَّرَ ‏","","",""],[17427,17427,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ‏ ‏فِتْنَةً ‏ ‏فَقَرَّبَهَا فَمَرَّ رَجُلٌ ‏ ‏مُتَقَنِّعٌ ‏ ‏فَقَالَ هَذَا يَوْمَئِذٍ عَلَى ‏ ‏الْهُدَى ‏ ‏قَالَ فَاتَّبَعْتُهُ حَتَّى أَخَذْتُ ‏ ‏بِضَبْعَيْهِ ‏ ‏فَحَوَّلْتُ وَجْهَهُ إِلَيْهِ وَكَشَفْتُ عَنْ رَأْسِهِ وَقُلْتُ هَذَا يَا رَسُولَ اللَّهِ قَالَ نَعَمْ فَإِذَا هُوَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[17428,17428,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ وَقَدْ شَبَّكْتُ بَيْنَ أَصَابِعِي فَقَالَ لِي يَا ‏ ‏كَعْبُ ‏ ‏إِذَا ‏ ‏كُنْتَ فِي الْمَسْجِدِ فَلَا تُشَبِّكْ بَيْنَ أَصَابِعِكَ فَأَنْتَ فِي صَلَاةٍ مَا انْتَظَرْتَ الصَّلَاةَ ‏","","",""],[17429,17429,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ أَنْ يَحْلِقَ رَأْسَهُ أَوْ ‏ ‏يَنْسُكَ ‏ ‏نُسُكًا أَوْ يَصُومَ ثَلَاثَةَ أَيَّامٍ أَوْ يُطْعِمَ فِرْقًا بَيْنَ سِتَّةِ مَسَاكِينَ ‏","","",""],[17430,17430,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ الْمُسَيَّبِ الْبَجَلِيُّ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا جَالِسٌ فِي ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسْنِدِي ظُهُورِنَا إِلَى قِبْلَةِ ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعَةُ ‏ ‏رَهْطٍ ‏ ‏أَرْبَعَةٌ ‏ ‏مَوَالِينَا ‏ ‏وَثَلَاثَةٌ مِنْ عَرَبِنَا إِذْ خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الظُّهْرِ حَتَّى انْتَهَى إِلَيْنَا فَقَالَ مَا يُجْلِسُكُمْ هَاهُنَا قُلْنَا يَا رَسُولَ اللَّهِ نَنْتَظِرُ الصَّلَاةَ قَالَ ‏ ‏فَأَرَمَّ ‏ ‏قَلِيلًا ثُمَّ رَفَعَ رَأْسَهُ فَقَالَ أَتَدْرُونَ مَا يَقُولُ رَبُّكُمْ عَزَّ وَجَلَّ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَإِنَّ رَبَّكُمْ عَزَّ وَجَلَّ يَقُولُ ‏ ‏مَنْ صَلَّى الصَّلَاةَ لِوَقْتِهَا وَحَافَظَ عَلَيْهَا وَلَمْ يُضَيِّعْهَا اسْتِخْفَافًا بِحَقِّهَا فَلَهُ عَلَيَّ عَهْدٌ أَنْ أُدْخِلَهُ الْجَنَّةَ وَمَنْ لَمْ يُصَلِّ لِوَقْتِهَا وَلَمْ يُحَافِظْ عَلَيْهَا وَضَيَّعَهَا اسْتِخْفَافًا بِحَقِّهَا فَلَا عَهْدَ لَهُ إِنْ شِئْتُ عَذَّبْتُهُ وَإِنْ شِئْتُ غَفَرْتُ لَهُ ‏","","",""],[17431,17431,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ ‏} ‏قَالُوا كَيْفَ نُصَلِّي عَلَيْكَ يَا نَبِيَّ اللَّهِ قَالَ قُولُوا ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَعَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَعَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ قَالَ وَنَحْنُ نَقُولُ وَعَلَيْنَا مَعَهُمْ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَلَا أَدْرِي أَشَيْءٌ زَادَهُ ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏مِنْ قِبَلِ نَفْسِهِ أَوْ شَيْءٌ رَوَاهُ ‏ ‏كَعْبٌ ‏","","",""],[17432,17432,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ وَهْبٍ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏فَسُئِلَ هَلْ أَمَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ غَيْرَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ نَعَمْ كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَلَمَّا كَانَ مِنْ ‏ ‏السَّحَرِ ‏ ‏ضَرَبَ عُنُقَ ‏ ‏رَاحِلَتِي ‏ ‏فَظَنَنْتُ أَنَّ لَهُ حَاجَةً ‏ ‏فَعَدَلْتُ ‏ ‏مَعَهُ فَانْطَلَقْنَا حَتَّى بَرَزْنَا عَنْ النَّاسِ فَنَزَلَ عَنْ ‏ ‏رَاحِلَتِهِ ‏ ‏ثُمَّ انْطَلَقَ فَتَغَيَّبَ عَنِّي حَتَّى مَا أَرَاهُ فَمَكَثَ طَوِيلًا ثُمَّ جَاءَ فَقَالَ حَاجَتَكَ يَا ‏ ‏مُغِيرَةُ ‏ ‏قُلْتُ مَا لِي حَاجَةٌ فَقَالَ هَلْ مَعَكَ مَاءٌ فَقُلْتُ نَعَمْ فَقُمْتُ إِلَى ‏ ‏قِرْبَةٍ ‏ ‏أَوْ إِلَى ‏ ‏سَطِيحَةٍ ‏ ‏مُعَلَّقَةٍ فِي آخِرَةِ ‏ ‏الرَّحْلِ ‏ ‏فَأَتَيْتُهُ بِمَاءٍ فَصَبَبْتُ عَلَيْهِ ‏ ‏فَغَسَلَ يَدَيْهِ فَأَحْسَنَ غَسْلَهُمَا ‏ ‏قَالَ وَأَشُكُّ أَقَالَ دَلَّكَهُمَا بِتُرَابٍ أَمْ لَا ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ ‏ ‏يَحْسِرُ ‏ ‏عَنْ يَدَيْهِ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ فَضَاقَتْ فَأَخْرَجَ يَدَيْهِ مِنْ تَحْتِهَا إِخْرَاجًا فَغَسَلَ وَجْهَهُ وَيَدَيْهِ ‏ ‏قَالَ فَيَجِيءُ فِي الْحَدِيثِ غَسْلُ الْوَجْهِ مَرَّتَيْنِ قَالَ لَا أَدْرِي أَهَكَذَا كَانَ أَمْ لَا ‏ ‏ثُمَّ مَسَحَ ‏ ‏بِنَاصِيَتِهِ ‏ ‏وَمَسَحَ عَلَى الْعِمَامَةِ وَمَسَحَ عَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏وَرَكِبْنَا فَأَدْرَكْنَا النَّاسَ وَقَدْ أُقِيمَتْ الصَّلَاةُ فَتَقَدَّمَهُمْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَقَدْ صَلَّى بِهِمْ رَكْعَةً وَهُمْ فِي الثَّانِيَةِ فَذَهَبْتُ أُوذِنُهُ فَنَهَانِي فَصَلَّيْنَا الرَّكْعَةَ الَّتِي أَدْرَكْنَا وَقَضَيْنَا الرَّكْعَةَ الَّتِي سُبِقْنَا ‏","","",""],[17433,17433,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ أَبُو يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ مِنْ أُمَّتِي قَوْمٌ ‏ ‏ظَاهِرِينَ ‏ ‏عَلَى النَّاسِ حَتَّى يَأْتِيَهُمْ أَمْرُ اللَّهِ وَهُمْ ‏ ‏ظَاهِرُونَ ‏","","",""],[17434,17434,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّهُ حَدَّثَ عَنِ ‏ ‏ابْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّهُ اسْتَشَارَهُمْ فِي ‏ ‏إِمْلَاصِ ‏ ‏الْمَرْأَةِ فَقَالَ لَهُ ‏ ‏الْمُغِيرَةُ ‏ ‏قَضَى ‏ ‏فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْغُرَّةِ ‏ ‏فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏إِنْ كُنْتَ صَادِقًا فَأْتِ بِأَحَدٍ يَعْلَمُ ذَلِكَ فَشَهِدَ ‏ ‏مُحَمَّدُ بْنُ مَسْلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى ‏ ‏بِهِ ‏","","",""],[17435,17435,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ لَهُ امْرَأَةً أَخْطُبُهَا فَقَالَ ‏ ‏اذْهَبْ فَانْظُرْ إِلَيْهَا فَإِنَّهُ ‏ ‏أَجْدَرُ ‏ ‏أَنْ ‏ ‏يُؤْدَمَ ‏ ‏بَيْنَكُمَا قَالَ فَأَتَيْتُ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَخَطَبْتُهَا إِلَى أَبَوَيْهَا وَأَخْبَرْتُهُمَا بِقَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَأَنَّهُمَا كَرِهَا ذَلِكَ قَالَ فَسَمِعَتْ ذَلِكَ الْمَرْأَةُ وَهِيَ فِي ‏ ‏خِدْرِهَا ‏ ‏فَقَالَتْ إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَكَ أَنْ تَنْظُرَ فَانْظُرْ وَإِلَّا فَإِنِّي ‏ ‏أَنْشُدُكَ ‏ ‏كَأَنَّهَا أَعْظَمَتْ ذَلِكَ عَلَيْهِ قَالَ فَنَظَرْتُ إِلَيْهَا فَتَزَوَّجْتُهَا فَذَكَرَ مِنْ مُوَافَقَتِهَا ‏","","",""],[17436,17436,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ نُضَيْلَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ امْرَأَتَيْنِ ضَرَبَتْ إِحْدَاهُمَا الْأُخْرَى بِعَمُودِ ‏ ‏فُسْطَاطٍ ‏ ‏فَقَتَلَتْهَا ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالدِّيَةِ عَلَى ‏ ‏عَصَبَةِ ‏ ‏الْقَاتِلَةِ وَفِيمَا فِي بَطْنِهَا ‏ ‏غُرَّةٌ ‏ ‏قَالَ الْأَعْرَابِيُّ ‏ ‏أَتُغَرِّمُنِي ‏ ‏مَنْ لَا أَكَلَ وَلَا شَرِبَ وَلَا ‏ ‏صَاحَ ‏ ‏فَاسْتَهَلَّ ‏ ‏مِثْلُ ذَلِكَ يُطَلُّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسَجْعٌ ‏ ‏كَسَجْعِ ‏ ‏الْأَعْرَابِ ‏ ‏وَبِمَا فِي بَطْنِهَا ‏ ‏غُرَّةٌ ‏","","",""],[17437,17437,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وحَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدَةُ بْنُ أَبِي لُبَابَةَ ‏ ‏أَنَّ ‏ ‏وَرَّادًا ‏ ‏مَوْلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏كَتَبَ إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏كَتَبَ ذَلِكَ الْكِتَابَ لَهُ ‏ ‏وَرَّادٌ ‏ ‏إِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ حِينَ يُسَلِّمُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏ ‏قَالَ ‏ ‏وَرَّادٌ ‏ ‏ثُمَّ وَفَدْتُ بَعْدَ ذَلِكَ عَلَى ‏ ‏مُعَاوِيَةَ ‏ ‏فَسَمِعْتُهُ عَلَى الْمِنْبَرِ يَأْمُرُ النَّاسَ بِذَلِكَ الْقَوْلِ وَيُعَلِّمُهُمُوهُ ‏","","",""],[17438,17438,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدٍ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبِيعَةَ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏مَاتَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُقَالُ لَهُ ‏ ‏قَرَظَةُ بْنُ كَعْبٍ ‏ ‏فَنِيحَ عَلَيْهِ فَخَرَجَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَصَعِدَ الْمِنْبَرَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ قَالَ مَا بَالُ النَّوْحِ فِي الْإِسْلَامِ أَمَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ كَذِبًا عَلَيَّ لَيْسَ كَكَذِبٍ عَلَى أَحَدٍ أَلَا وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[17439,17439,"","","‏ ‏أَلَا وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏يُنَحْ ‏ ‏عَلَيْهِ يُعَذَّبْ بِمَا ‏ ‏يُنَاحُ ‏ ‏بِهِ عَلَيْهِ ‏","","",""],[17440,17440,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ أَبُو مُحَمَّدٍ الْكِلَابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏وَضَّأْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ وَمَسَحَ بِرَأْسِهِ وَمَسَحَ عَلَى ‏ ‏خُفَّيْهِ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَا أَنْزِعُ ‏ ‏خُفَّيْكَ ‏ ‏قَالَ لَا ‏ ‏إِنِّي أَدْخَلْتُهُمَا وَهُمَا طَاهِرَتَانِ ثُمَّ لَمْ أَمْشِ حَافِيًا بَعْدُ ثُمَّ صَلَّى صَلَاةَ الصُّبْحِ ‏","","",""],[17441,17441,"","","‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمُتَعَالِ بْنُ عَبْدِ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُجَالِدُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏كَسَفَتْ الشَّمْسُ ‏ ‏ضَحْوَةً ‏ ‏حَتَّى اشْتَدَّتْ ظُلْمَتُهَا فَقَامَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَصَلَّى بِالنَّاسِ فَقَامَ قَدْرَ مَا يَقْرَأُ سُورَةً مِنْ ‏ ‏الْمَثَانِي ‏ ‏ثُمَّ رَكَعَ مِثْلَ ذَلِكَ ثُمَّ رَفَعَ رَأْسَهُ ثُمَّ رَكَعَ مِثْلَ ذَلِكَ ثُمَّ رَفَعَ رَأْسَهُ فَقَامَ مِثْلَ ذَلِكَ ثُمَّ رَكَعَ الثَّانِيَةَ مِثْلَ ذَلِكَ ثُمَّ إِنَّ الشَّمْسَ ‏ ‏تَجَلَّتْ ‏ ‏فَسَجَدَ ثُمَّ قَامَ قَدْرَ مَا يَقْرَأُ سُورَةً ثُمَّ رَكَعَ وَسَجَدَ ثُمَّ انْصَرَفَ فَصَعِدَ الْمِنْبَرَ فَقَالَ إِنَّ الشَّمْسَ كَسَفَتْ يَوْمَ تُوُفِّيَ ‏ ‏إِبْرَاهِيمُ ابْنُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَإِنَّمَا هُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّ وَجَلَّ فَإِذَا انْكَسَفَ وَاحِدٌ مِنْهُمَا فَافْزَعُوا إِلَى الصَّلَاةِ ثُمَّ نَزَلَ فَحَدَّثَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي الصَّلَاةِ فَجَعَلَ يَنْفُخُ بَيْنَ يَدَيْهِ ثُمَّ إِنَّهُ مَدَّ يَدَهُ كَأَنَّهُ يَتَنَاوَلُ شَيْئًا فَلَمَّا انْصَرَفَ قَالَ إِنَّ النَّارَ ‏ ‏أُدْنِيَتْ ‏ ‏مِنِّي حَتَّى نَفَخْتُ حَرَّهَا عَنْ وَجْهِي فَرَأَيْتُ فِيهَا صَاحِبَ ‏ ‏الْمِحْجَنِ ‏ ‏وَالَّذِي بَحَرَ الْبَحِيرَةَ وَصَاحِبَةَ ‏ ‏حِمْيَرَ ‏ ‏صَاحِبَةَ ‏ ‏الْهِرَّةِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْمُجَالِدُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏مِثْلَهُ ‏","","",""],[17442,17442,"","","‏ ‏حَدَّثَنِي ‏ ‏أَبُو النَّضْرِ الْحَارِثُ بْنُ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْهُذَلِيَّتَيْنِ ‏ ‏أَنَّ ‏ ‏الْعَقْلَ ‏ ‏عَلَى ‏ ‏الْعَصَبَةِ ‏ ‏وَأَنَّ الْمِيرَاثَ لِلْوَرَثَةِ وَأَنَّ فِي الْجَنِينِ ‏ ‏غُرَّةً ‏","","",""],[17443,17443,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي نُعْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏أَنَّهُ سَافَرَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَادِيًا ‏ ‏فَقَضَى حَاجَتَهُ ثُمَّ خَرَجَ فَأَتَاهُ فَتَوَضَّأَ فَخَلَعَ ‏ ‏خُفَّيْهِ ‏ ‏فَتَوَضَّأَ فَلَمَّا فَرَغَ وَجَدَ رِيحًا بَعْدَ ذَلِكَ فَعَادَ فَخَرَجَ فَتَوَضَّأَ وَمَسَحَ عَلَى ‏ ‏خُفَّيْهِ ‏ ‏فَقُلْتُ يَا نَبِيَّ اللَّهِ نَسِيتَ لَمْ تَخْلَعْ ‏ ‏الْخُفَّيْنِ ‏ ‏قَالَ كَلَّا بَلْ أَنْتَ نَسِيتَ بِهَذَا أَمَرَنِي رَبِّي عَزَّ وَجَلَّ ‏","","",""],[17444,17444,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ ‏ ‏وَقَدْ كُنْتُ حَفِظْتُ مِنْ ‏ ‏كَثِيرٍ مِنْ عُلَمَائِنَا ‏ ‏بِالْمَدِينَةِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَمْرِو بْنِ حَزْمٍ ‏ ‏كَانَ ‏ ‏يَرْوِي عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏أَحَادِيثَ مِنْهَا ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ ‏","","",""],[17445,17445,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ كَرِهَ لَكُمْ ثَلَاثًا قِيلَ وَقَالَ وَكَثْرَةَ السُّؤَالِ وَإِضَاعَةَ الْمَالِ وَحَرَّمَ عَلَيْكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأْدَ ‏ ‏الْبَنَاتِ ‏ ‏وَعُقُوقَ ‏ ‏الْأُمَّهَاتِ وَمَنَعَ ‏ ‏وَهَاتِ ‏","","",""],[17446,17446,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ نُضَيْلَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ امْرَأَةً ضَرَبَتْهَا امْرَأَةٌ بِعَمُودِ ‏ ‏فُسْطَاطٍ ‏ ‏فَقَتَلَتْهَا وَهِيَ حُبْلَى فَأُتِيَ بِهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَضَى فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عَصَبَةِ ‏ ‏الْقَاتِلَةِ ‏ ‏بِالدِّيَةِ ‏ ‏وَفِي الْجَنِينِ ‏ ‏غُرَّةٌ ‏ ‏فَقَالَ ‏ ‏عَصَبَتُهَا ‏ ‏أَنْدِي ‏ ‏مَنْ لَا طَعِمَ وَلَا شَرِبَ وَلَا صَاحَ ‏ ‏فَاسْتَهَلَّ ‏ ‏مِثْلُ ذَلِكَ يُطَلُّ فَقَالَ ‏ ‏سَجْعٌ ‏ ‏مِثْلُ ‏ ‏سَجْعِ ‏ ‏الْأَعْرَابِ ‏ ‏و قَالَ ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏عُبَيْدًا ‏","","",""],[17447,17447,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏مَنْصُورٌ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُبَيْدِ بْنِ نُضَيْلَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ امْرَأَتَيْنِ كَانَتَا تَحْتَ رَجُلٍ فَغَارَتَا فَضَرَبَتْهَا بِعَمُودِ ‏ ‏فُسْطَاطٍ ‏ ‏فَقَتَلَتْهَا ‏ ‏فَاخْتَصَمُوا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَحَدُهُمَا يَا رَسُولَ اللَّهِ كَيْفَ ‏ ‏نَدِي ‏ ‏مَنْ لَا أَكَلَ وَلَا شَرِبَ وَلَا صَاحَ ‏ ‏فَاسْتَهَلَّ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسَجْعٌ ‏ ‏كَسَجْعِ ‏ ‏الْأَعْرَابِ ‏ ‏قَالَ فَقَضَى فِيهِ ‏ ‏غُرَّةً ‏ ‏قَالَ وَجَعَلَهُ عَلَى ‏ ‏عَاقِلَةِ ‏ ‏الْمَرْأَةِ ‏","","",""],[17448,17448,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏وَحَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى ‏ ‏سُبَاطَةِ ‏ ‏بَنِي فُلَانٍ فَبَالَ قَائِمًا ‏ ‏قَالَ ‏ ‏حَمَّادُ بْنُ أَبِي سُلَيْمَانَ ‏ ‏فَفَحَّجَ ‏ ‏رِجْلَيْهِ ‏","","",""],[17449,17449,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ ‏ ‏بِحُجْزَةِ ‏ ‏سُفْيَانَ بْنِ أَبِي سَهْلٍ ‏ ‏وَهُوَ يَقُولُ يَا ‏ ‏سُفْيَانُ بْنَ أَبِي سَهْلٍ ‏ ‏لَا ‏ ‏تُسْبِلْ ‏ ‏إِزَارَكَ ‏ ‏فَإِنَّ اللَّهَ لَا يُحِبُّ ‏ ‏الْمُسْبِلِينَ ‏","","",""],[17450,17450,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏مَسْلَمَةُ بْنُ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ وَلَدِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُثْلَةِ ‏","","",""],[17451,17451,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّهُ صَحِبَ قَوْمًا مِنْ الْمُشْرِكِينَ فَوَجَدَ مِنْهُمْ غَفْلَةً فَقَتَلَهُمْ وَأَخَذَ أَمْوَالَهُمْ فَجَاءَ بِهَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَبَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَقْبَلَهَا ‏","","",""],[17452,17452,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏خَطَبْتُ امْرَأَةً فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَظَرْتَ إِلَيْهَا قُلْتُ لَا قَالَ ‏ ‏فَانْظُرْ إِلَيْهَا فَإِنَّهُ ‏ ‏أَحْرَى ‏ ‏أَنْ ‏ ‏يُؤْدَمَ ‏ ‏بَيْنَكُمَا ‏","","",""],[17453,17453,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏مَا سَأَلَ أَحَدٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرَ مِمَّا سَأَلْتُ أَنَا عَنْهُ فَقَالَ إِنَّهُ لَا يَضُرُّكَ قَالَ قُلْتُ إِنَّهُمْ يَقُولُونَ مَعَهُ نَهَرٌ وَكَذَا وَكَذَا قَالَ ‏ ‏هُوَ أَهْوَنُ عَلَى اللَّهِ مِنْ ذَاكَ ‏","","",""],[17454,17454,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ قَالَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى ظُهُورِ ‏ ‏الْخُفَّيْنِ ‏ ‏حَدَّثَنَاه ‏ ‏سُرَيْجٌ ‏ ‏والْهَاشِمِيُّ ‏ ‏أَيْضًا ‏","","",""],[17455,17455,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏بَكْرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَصْلَتَانِ لَا أَسْأَلُ عَنْهُمَا أَحَدًا مِنْ النَّاسِ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَهُمَا ‏ ‏صَلَاةُ الْإِمَامِ خَلْفَ الرَّجُلِ مِنْ رَعِيَّتِهِ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى خَلْفَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏رَكْعَةً مِنْ صَلَاةِ الصُّبْحِ وَمَسْحُ الرَّجُلِ عَلَى ‏ ‏خُفَّيْهِ ‏ ‏وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى ‏ ‏الْخُفَّيْنِ ‏","","",""],[17456,17456,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏وَرَّادٌ ‏ ‏كَاتِبُ ‏ ‏الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏مُعَاوِيَةُ ‏ ‏إِلَى ‏ ‏الْمُغِيرَةِ ‏ ‏اكْتُبْ إِلَيَّ بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ إِذَا صَلَّى فَفَرَغَ قَالَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏قَالَ وَأَظُنُّهُ قَالَ وَحْدَهُ لَا شَرِيكَ لَهُ ‏ ‏لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏","","",""],[17457,17457,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَقَضَى حَاجَتَهُ ثُمَّ جِئْتُهُ ‏ ‏بِإِدَاوَةٍ ‏ ‏مِنْ مَاءٍ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ قَالَ فَلَمْ يَقْدِرْ أَنْ يُخْرِجَ يَدَيْهِ مِنْ كُمَّيْهَا فَأَخْرَجَ يَدَيْهِ مِنْ أَسْفَلِهَا ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى ‏ ‏خُفَّيْهِ ‏","","",""],[17458,17458,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏وَلَدِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَهَبَ لِحَاجَتِهِ فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏فَذَهَبْتُ مَعَهُ بِمَاءٍ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَكَبْتُ عَلَيْهِ مَاءً ‏ ‏فَغَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ يُخْرِجُ يَدَيْهِ مِنْ كُمِّ ‏ ‏جُبَّتِهِ ‏ ‏فَلَمْ يَسْتَطِعْ مِنْ ضِيقِ كُمِّ ‏ ‏الْجُبَّةِ ‏ ‏فَأَخْرَجَهَا مِنْ تَحْتِ ‏ ‏جُبَّتِهِ ‏ ‏فَغَسَلَ يَدَيْهِ وَمَسَحَ رَأْسَهُ وَمَسَحَ عَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏يَؤُمُّهُمْ ‏ ‏وَقَدْ صَلَّى بِهِمْ رَكْعَةً فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُمْ الرَّكْعَةَ الَّتِي بَقِيَتْ عَلَيْهِمْ فَلَمَّا فَرَغَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَحْسَنْتُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ زِيَادٍ ‏ ‏مِنْ وَلَدِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏فَذَكَرَ هَذَا الْحَدِيثَ ‏ ‏قَالَ ‏ ‏مُصْعَبٌ ‏ ‏وَأَخْطَأَ فِيهِ ‏ ‏مَالِكٌ ‏ ‏خَطَأً قَبِيحًا ‏","","",""],[17459,17459,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ الْحَدَّادُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُبَيْدِ اللَّهِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّاكِبُ خَلْفَ الْجِنَازَةِ وَالْمَاشِي حَيْثُ شَاءَ مِنْهَا وَالطِّفْلُ يُصَلَّى عَلَيْهِ ‏","","",""],[17460,17460,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَلَمَّا صَلَّى رَكْعَتَيْنِ قَامَ وَلَمْ يَجْلِسْ فَسَبَّحَ بِهِ مَنْ خَلْفَهُ فَأَشَارَ إِلَيْهِمْ أَنْ قُومُوا فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ سَلَّمَ ثُمَّ سَجَدَ سَجْدَتَيْنِ ثُمَّ قَالَ هَكَذَا صَنَعَ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17461,17461,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ ‏ ‏مَسْجِدَ الْجَامِعِ ‏ ‏فَإِذَا ‏ ‏عَمْرُو بْنُ وَهْبٍ الثَّقَفِيُّ ‏ ‏قَدْ دَخَلَ مِنْ النَّاحِيَةِ الْأُخْرَى فَالْتَقَيْنَا قَرِيبًا مِنْ وَسَطِ الْمَسْجِدِ فَابْتَدَأَنِي بِالْحَدِيثِ وَكَانَ يُحِبُّ مَا سَاقَ إِلَيَّ مِنْ خَيْرٍ فَابْتَدَأَنِي بِالْحَدِيثِ فَقَالَ كُنَّا عِنْدَ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏فَزَادَهُ فِي نَفْسِي تَصْدِيقًا الَّذِي قَرَّبَ بِهِ الْحَدِيثَ قَالَ قُلْنَا هَلْ أَمَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ مِنْ هَذِهِ الْأُمَّةِ غَيْرَ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ نَعَمْ كُنَّا فِي سَفَرِ كَذَا وَكَذَا فَلَمَّا كَانَ فِي ‏ ‏السَّحَرِ ‏ ‏ضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُنُقَ ‏ ‏رَاحِلَتِهِ ‏ ‏وَانْطَلَقَ فَتَبِعْتُهُ فَتَغَيَّبَ عَنِّي سَاعَةً ثُمَّ جَاءَ فَقَالَ حَاجَتَكَ فَقُلْتُ لَيْسَتْ لِي حَاجَةٌ يَا رَسُولَ اللَّهِ قَالَ هَلْ مِنْ مَاءٍ قُلْتُ نَعَمْ فَصَبَبْتُ عَلَيْهِ ‏ ‏فَغَسَلَ يَدَيْهِ ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ ‏ ‏يَحْسِرُ ‏ ‏عَنْ ذِرَاعَيْهِ وَكَانَتْ عَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏لَهُ شَامِيَّةٌ فَضَاقَتْ فَأَدْخَلَ ‏ ‏يَدَيْهِ فَأَخْرَجَهُمَا مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ وَجْهَهُ وَغَسَلَ ذِرَاعَيْهِ وَمَسَحَ ‏ ‏بِنَاصِيَتِهِ ‏ ‏وَمَسَحَ عَلَى الْعِمَامَةِ وَعَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏ثُمَّ لَحِقْنَا النَّاسَ وَقَدْ أُقِيمَتْ الصَّلَاةُ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏يَؤُمُّهُمْ وَقَدْ صَلَّى رَكْعَةً فَذَهَبْتُ لِأُوذِنَهُ فَنَهَانِي فَصَلَّيْنَا الَّتِي أَدْرَكْنَا وَقَضَيْنَا الَّتِي سُبِقْنَا بِهَا ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ وَهْبٍ ‏ ‏يَعْنِي ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[17462,17462,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَزَالُ نَاسٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى الْحَقِّ ظَاهِرِينَ حَتَّى يَأْتِيَهُمْ أَمْرُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[17463,17463,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏مَا سَأَلَ أَحَدٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدَّجَّالِ ‏ ‏أَكْثَرَ مِمَّا سَأَلْتُهُ عَنْهُ فَقَالَ لِي أَيْ بُنَيَّ وَمَا ‏ ‏يُنْصِبُكَ ‏ ‏مِنْهُ إِنَّهُ لَنْ يَضُرَّكَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُمْ يَزْعُمُونَ أَنَّ مَعَهُ جِبَالَ الْخُبْزِ وَأَنْهَارَ الْمَاءِ فَقَالَ ‏ ‏هُوَ أَهْوَنُ عَلَى اللَّهِ عَزَّ وَجَلَّ مِنْ ذَاكَ ‏","","",""],[17464,17464,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏كَاتِبِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏لَوْ رَأَيْتُ رَجُلًا مَعَ امْرَأَتِي لَضَرَبْتُهُ بِالسَّيْفِ غَيْرَ ‏ ‏مُصْفَحٍ ‏ ‏فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَتَعْجَبُونَ مِنْ غَيْرَةِ ‏ ‏سَعْدٍ ‏ ‏وَاللَّهِ لَأَنَا أَغْيَرُ مِنْهُ وَاللَّهُ أَغْيَرُ مِنِّي وَمِنْ أَجْلِ غَيْرَةِ اللَّهِ حَرَّمَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا شَخْصَ أَغْيَرُ مِنْ اللَّهِ وَلَا شَخْصَ أَحَبُّ إِلَيْهِ الْعُذْرُ مِنْ اللَّهِ مِنْ أَجْلِ ذَلِكَ بَعَثَ اللَّهُ الْمُرْسَلِينَ مُبَشِّرِينَ وَمُنْذِرِينَ وَلَا شَخْصَ أَحَبُّ إِلَيْهِ ‏ ‏مِدْحَةٌ ‏ ‏مِنْ اللَّهِ مِنْ أَجْلِ ذَلِكَ وَعَدَ اللَّهُ الْجَنَّةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏بِإِسْنَادِهِ مِثْلَهُ سَوَاءً ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ الْقَوَارِيرِيُّ ‏ ‏لَيْسَ حَدِيثٌ أَشَدَّ عَلَى ‏ ‏الْجَهْمِيَّةِ ‏ ‏مِنْ هَذَا الْحَدِيثِ قَوْلِهِ لَا شَخْصَ أَحَبُّ إِلَيْهِ مِدْحَةٌ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[17465,17465,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إيَادًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏قَبِيصَةَ بْنِ بُرْمَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ مَا كَانَ يُسَافِرُ فَسِرْنَا حَتَّى إِذَا كُنَّا فِي وَجْهِ ‏ ‏السَّحَرِ ‏ ‏انْطَلَقَ حَتَّى ‏ ‏تَوَارَى ‏ ‏عَنِّي فَضَرَبَ ‏ ‏الْخَلَاءَ ‏ ‏ثُمَّ جَاءَ ‏ ‏فَدَعَا بِطَهُورٍ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ فَأَدْخَلَ يَدَهُ مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ وَيَدَيْهِ وَمَسَحَ بِرَأْسِهِ وَمَسَحَ عَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ وَكَانَ إِذَا ذَهَبَ أَبْعَدَ فِي الْمَذْهَبِ فَذَهَبَ ‏ ‏لِحَاجَتِهِ ‏ ‏وَقَالَ يَا ‏ ‏مُغِيرَةُ ‏ ‏اتْبَعْنِي بِمَاءٍ فَذَكَرَ الْحَدِيثَ ‏","","",""],[17466,17466,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏تَخَلَّفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَضَى ‏ ‏حَاجَتَهُ ‏ ‏فَقَالَ هَلْ مَعَكَ ‏ ‏طَهُورٌ ‏ ‏قَالَ فَاتَّبَعْتُهُ ‏ ‏بِمِيضَأَةٍ ‏ ‏فِيهَا مَاءٌ ‏ ‏فَغَسَلَ كَفَّيْهِ وَوَجْهَهُ ثُمَّ ذَهَبَ ‏ ‏يَحْسِرُ ‏ ‏عَنْ ذِرَاعَيْهِ وَكَانَ فِي يَدَيْ ‏ ‏الْجُبَّةِ ‏ ‏ضِيقٌ فَأَخْرَجَ يَدَيْهِ مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ ذِرَاعَيْهِ ثُمَّ مَسَحَ عَلَى عِمَامَتِهِ ‏ ‏وَخُفَّيْهِ ‏ ‏وَرَكِبَ وَرَكِبْتُ ‏ ‏رَاحِلَتِي ‏ ‏فَانْتَهَيْنَا إِلَى الْقَوْمِ وَقَدْ صَلَّى بِهِمْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏رَكْعَةً فَلَمَّا أَحَسَّ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَهَبَ يَتَأَخَّرُ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ أَنْ يُتِمَّ الصَّلَاةَ وَقَالَ قَدْ أَحْسَنْتَ كَذَلِكَ فَافْعَلْ ‏","","",""],[17467,17467,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّهُ قَامَ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ فَسَبَّحُوا بِهِ فَلَمْ يَجْلِسْ فَلَمَّا قَضَى صَلَاتَهُ سَجَدَ سَجْدَتَيْنِ بَعْدَ التَّسْلِيمِ ثُمَّ قَالَ هَكَذَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17468,17468,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زِيَادُ بْنُ جُبَيْرٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرَّاكِبُ خَلْفَ الْجِنَازَةِ وَالْمَاشِي أَمَامَهَا قَرِيبًا عَنْ يَمِينِهَا أَوْ ‏ ‏عَنْ يَسَارِهَا وَالسِّقْطُ يُصَلَّى عَلَيْهِ ‏ ‏وَيُدْعَى لِوَالِدَيْهِ بِالْمَغْفِرَةِ وَالرَّحْمَةِ ‏","","",""],[17469,17469,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعْدٌ ‏ ‏وَيَعْقُوبُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبَّادُ بْنُ زِيَادٍ ‏ ‏قَالَ ‏ ‏سَعْدُ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَخَلَّفْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَتَبَرَّزَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ رَجَعَ إِلَيَّ وَمَعِي ‏ ‏الْإِدَاوَةُ ‏ ‏قَالَ فَصَبَبْتُ عَلَى يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏اسْتَنْثَرَ ‏ ‏قَالَ ‏ ‏يَعْقُوبُ ‏ ‏ثُمَّ تَمَضْمَضَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثَ مَرَّاتٍ ثُمَّ أَرَادَ أَنْ يَغْسِلَ يَدَيْهِ قَبْلَ أَنْ يُخْرِجَهُمَا مِنْ كُمَّيْ ‏ ‏جُبَّتِهِ ‏ ‏فَضَاقَ عَنْهُ كُمَّاهَا فَأَخْرَجَ يَدَهُ مِنْ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ يَدَهُ الْيُمْنَى ثَلَاثَ مَرَّاتٍ وَيَدَهُ الْيُسْرَى ثَلَاثَ مَرَّاتٍ وَمَسَحَ ‏ ‏بِخُفَّيْهِ ‏ ‏وَلَمْ يَنْزِعْهُمَا ثُمَّ ‏ ‏عَمَدَ ‏ ‏إِلَى النَّاسِ فَوَجَدَهُمْ قَدْ قَدَّمُوا ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏يُصَلِّي بِهِمْ فَأَدْرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِحْدَى الرَّكْعَتَيْنِ فَصَلَّى مَعَ النَّاسِ الرَّكْعَةَ الْآخِرَةَ بِصَلَاةِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏فَلَمَّا سَلَّمَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُتِمُّ صَلَاتَهُ فَأَفْزَعَ الْمُسْلِمِينَ فَأَكْثَرُوا التَّسْبِيحَ فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْبَلَ عَلَيْهِمْ فَقَالَ ‏ ‏قَدْ أَحْسَنْتُمْ وَأَصَبْتُمْ ‏ ‏يَغْبِطُهُمْ ‏ ‏أَنْ صَلَّوْا الصَّلَاةَ لِوَقْتِهَا ‏","","",""],[17470,17470,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَوَجَدَ مِنِّي رِيحَ الثُّومِ فَقَالَ ‏ ‏مَنْ أَكَلَ الثُّومَ قَالَ فَأَخَذْتُ يَدَهُ فَأَدْخَلْتُهَا فَوَجَدَ صَدْرِي ‏ ‏مَعْصُوبًا ‏ ‏قَالَ إِنَّ لَكَ عُذْرًا ‏","","",""],[17471,17471,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ نُضَيْلَةَ ‏ ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏الْخُزَاعِيُّ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ ضُرَّتَيْنِ ضَرَبَتْ إِحْدَاهُمَا الْأُخْرَى بِعَمُودِ ‏ ‏فُسْطَاطٍ ‏ ‏فَقَتَلَتْهَا ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالدِّيَةِ ‏ ‏عَلَى ‏ ‏عَصَبَةِ ‏ ‏الْقَاتِلَةِ وَفِيمَا فِي بَطْنِهَا ‏ ‏غُرَّةٌ ‏ ‏قَالَ الْأَعْرَابِيُّ ‏ ‏أَتُغَرِّمُنِي ‏ ‏مَنْ لَا أَكَلَ وَلَا شَرِبَ وَلَا صَاحَ ‏ ‏فَاسْتَهَلَّ ‏ ‏فَمِثْلُ ذَلِكَ يُطَلُّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجْعٌ ‏ ‏كَسَجْعِ ‏ ‏الْأَعْرَابِ ‏ ‏وَلِمَا فِي بَطْنِهَا ‏ ‏غُرَّةٌ ‏","","",""],[17472,17472,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏يَقُولُ ‏ ‏انْكَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ مَاتَ ‏ ‏إِبْرَاهِيمُ ‏ ‏فَقَالَ النَّاسُ انْكَسَفَتْ لِمَوْتِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا رَأَيْتُمُوهُ فَادْعُوا اللَّهَ وَصَلُّوا حَتَّى تَنْكَشِفَ ‏","","",""],[17473,17473,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَشْوَعَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏كَاتِبُ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏مُعَاوِيَةُ ‏ ‏إِلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنْ اكْتُبْ إِلَيَّ بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَتَبَ إِلَيْهِ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ كَرِهَ لَكُمْ قِيلَ وَقَالَ وَإِضَاعَةَ الْمَالِ وَكَثْرَةَ السُّؤَالِ ‏","","",""],[17474,17474,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏الْعَقَّارِ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ اكْتَوَى أَوْ ‏ ‏اسْتَرْقَى ‏ ‏فَقَدْ بَرِئَ مِنْ التَّوَكُّلِ ‏","","",""],[17475,17475,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏قَالَ ‏ ‏الرَّاكِبُ يَسِيرُ خَلْفَ الْجِنَازَةِ وَالْمَاشِي يَمْشِي خَلْفَهَا وَأَمَامَهَا وَيَمِينَهَا وَشِمَالَهَا قَرِيبًا وَالسِّقْطُ يُصَلَّى عَلَيْهِ يُدْعَى لِوَالِدَيْهِ بِالْعَافِيَةِ وَالرَّحْمَةِ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏وَأَهْلُ ‏ ‏زِيَادٍ ‏ ‏يَذْكُرُونَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَّا أَنَا فَلَا أَحْفَظُهُ ‏","","",""],[17476,17476,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ وَهْبٍ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏فَسُئِلَ هَلْ أَمَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ غَيْرَ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَ نَعَمْ قَالَ فَزَادَهُ عِنْدِي تَصْدِيقًا الَّذِي قَرَّبَ بِهِ الْحَدِيثَ ‏ ‏قَالَ كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَلَمَّا كَانَ مِنْ ‏ ‏السَّحَرِ ‏ ‏ضَرَبَ عَقِبَ ‏ ‏رَاحِلَتِي ‏ ‏فَظَنَنْتُ أَنَّ لَهُ ‏ ‏حَاجَةً ‏ ‏فَعَدَلْتُ ‏ ‏مَعَهُ فَانْطَلَقْنَا حَتَّى ‏ ‏بَرَزْنَا ‏ ‏عَنْ النَّاسِ فَنَزَلَ عَنْ ‏ ‏رَاحِلَتِهِ ‏ ‏ثُمَّ انْطَلَقَ فَتَغَيَّبَ عَنِّي حَتَّى مَا أَرَاهُ فَمَكَثَ طَوِيلًا ثُمَّ جَاءَ فَقَالَ حَاجَتَكَ يَا ‏ ‏مُغِيرَةُ ‏ ‏قُلْتُ مَا لِي حَاجَةٌ فَقَالَ هَلْ مَعَكَ مَاءٌ قُلْتُ نَعَمْ فَقُمْتُ إِلَى ‏ ‏قِرْبَةٍ ‏ ‏أَوْ قَالَ ‏ ‏سَطِيحَةٍ ‏ ‏مُعَلَّقَةٍ فِي آخِرَةِ ‏ ‏الرَّحْلِ ‏ ‏فَأَتَيْتُهُ بِهَا فَصَبَبْتُ عَلَيْهِ ‏ ‏فَغَسَلَ يَدَيْهِ فَأَحْسَنَ غَسْلَهُمَا ‏ ‏قَالَ وَأَشُكُّ أَقَالَ دَلَّكَهُمَا بِتُرَابٍ أَمْ لَا ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ ‏ ‏يَحْسِرُ ‏ ‏عَنْ يَدِهِ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ ضَيِّقَةُ الْكُمِّ فَضَاقَتْ فَأَخْرَجَ يَدَيْهِ مِنْ تَحْتِهَا إِخْرَاجًا فَغَسَلَ وَجْهَهُ وَيَدَيْهِ ‏ ‏قَالَ فَيَجِيءُ فِي الْحَدِيثِ غَسْلُ الْوَجْهِ مَرَّتَيْنِ فَلَا أَدْرِي أَهَكَذَا كَانَ أَمْ لَا ‏ ‏ثُمَّ مَسَحَ ‏ ‏بِنَاصِيَتِهِ ‏ ‏وَمَسَحَ عَلَى الْعِمَامَةِ وَمَسَحَ عَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏ثُمَّ رَكِبْنَا فَأَدْرَكْنَا النَّاسَ وَقَدْ أُقِيمَتْ الصَّلَاةُ فَتَقَدَّمَهُمْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَقَدْ صَلَّى بِهِمْ رَكْعَةً وَهُمْ فِي الثَّانِيَةِ فَذَهَبْتُ أُوذِنُهُ فَنَهَانِي فَصَلَّيْنَا الرَّكْعَةَ الَّتِي أَدْرَكْنَا وَقَضَيْنَا الَّتِي سُبِقْنَا ‏","","",""],[17477,17477,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُسَيَّبَ بْنَ رَافِعٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏وَرَّادٍ ‏ ‏كَاتِبِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ ‏ ‏كَتَبَ إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا سَلَّمَ قَالَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏","","",""],[17478,17478,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏مَيْمُونَ بْنَ أَبِي شَبِيبٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ رَوَى عَنِّي حَدِيثًا وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَذَّابِينَ ‏","","",""],[17479,17479,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏بَيَانِ بْنِ بِشْرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي مَعَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الظُّهْرِ ‏ ‏بِالْهَاجِرَةِ ‏ ‏فَقَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[17480,17480,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آخِذًا ‏ ‏بِحُجْزَةِ ‏ ‏سُفْيَانَ بْنِ أَبِي سَهْلٍ ‏ ‏فَقَالَ يَا ‏ ‏سُفْيَانُ بْنَ أَبِي سَهْلٍ ‏ ‏لَا ‏ ‏تُسْبِلْ ‏ ‏إِزَارَكَ ‏ ‏فَإِنَّ اللَّهَ لَا يُحِبُّ ‏ ‏الْمُسْبِلِينَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عُقْبَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ جَابِرٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏","","",""],[17481,17481,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَقَالَ لِي يَا ‏ ‏مُغِيرَةُ ‏ ‏خُذْ ‏ ‏الْإِدَاوَةَ ‏ ‏قَالَ فَأَخَذْتُهَا قَالَ ثُمَّ انْطَلَقْتُ مَعَهُ فَانْطَلَقَ حَتَّى ‏ ‏تَوَارَى ‏ ‏عَنِّي فَقَضَى حَاجَتَهُ ثُمَّ جَاءَ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ قَالَ فَذَهَبَ يُخْرِجُ يَدَيْهِ مِنْهَا فَضَاقَتْ فَأَخْرَجَ يَدَيْهِ مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏فَصَبَبْتُ عَلَيْهِ ‏ ‏فَتَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ مَسَحَ ‏ ‏خُفَّيْهِ ‏ ‏ثُمَّ صَلَّى ‏","","",""],[17482,17482,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ سَوْقَةَ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏مَوْلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏مُعَاوِيَةُ ‏ ‏إِلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنْ اكْتُبْ إِلَيَّ بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ بَيْنَكَ وَبَيْنَهُ أَحَدٌ قَالَ فَأَمْلَى عَلَيَّ وَكَتَبْتُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ حَرَّمَ ثَلَاثًا وَنَهَى عَنْ ثَلَاثٍ فَأَمَّا الثَّلَاثُ اللَّاتِي نَهَى اللَّهُ عَنْهُنَّ فَقِيلَ وَقَالَ وَإِلْحَافُ السُّؤَالِ وَإِضَاعَةُ الْمَالِ ‏","","",""],[17483,17483,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏غَيْرُ وَاحِدٍ مِنْهُمْ ‏ ‏مُغِيرَةُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏كَاتِبِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏كَتَبَ إِلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏اكْتُبْ إِلَيَّ بِحَدِيثٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَكَتَبَ إِلَيْهِ ‏ ‏الْمُغِيرَةُ ‏ ‏إِنِّي سَمِعْتُهُ يَقُولُ عِنْدَ انْصِرَافِهِ مِنْ الصَّلَاةِ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ثَلَاثَ مَرَّاتٍ وَكَانَ يَنْهَى عَنْ قِيلَ ‏ ‏وَقَالَ وَكَثْرَةِ السُّؤَالِ وَإِضَاعَةِ الْمَالِ وَمَنْعٍ ‏ ‏وَهَاتِ ‏ ‏وَعُقُوقِ ‏ ‏الْأُمَّهَاتِ ‏ ‏وَوَأْدِ ‏ ‏الْبَنَاتِ ‏","","",""],[17484,17484,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏رَفَعَهُ إِلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَغَمَزَ ظَهْرِي ‏ ‏أَوْ كَتِفِي ‏ ‏بِشَيْءٍ كَانَ مَعَهُ قَالَ وَتَبِعْتُهُ فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَتَهُ ‏ ‏ثُمَّ جَاءَ فَقَالَ أَمَعَكَ مَاءٌ قُلْتُ نَعَمْ وَمَعِي ‏ ‏سَطِيحَةٌ ‏ ‏مِنْ مَاءٍ ‏ ‏فَغَسَلَ وَجْهَهُ وَكَانَتْ عَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ فَأَدْخَلَ يَدَهُ فَرَفَعَ ‏ ‏الْجُبَّةَ ‏ ‏عَلَى ‏ ‏عَاتِقِهِ ‏ ‏وَأَخْرَجَ يَدَيْهِ مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ ذِرَاعَيْهِ وَمَسَحَ عَلَى الْعِمَامَةِ قَالَ وَذَكَرَ ‏ ‏النَّاصِيَةَ ‏ ‏بِشَيْءٍ وَمَسَحَ عَلَى ‏ ‏خُفَّيْهِ ‏ ‏ثُمَّ أَقْبَلْنَا فَأَدْرَكْنَا الْقَوْمَ فِي صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏يَؤُمُّهُمْ وَقَدْ صَلَّوْا رَكْعَةً فَذَهَبْتُ ‏ ‏لِأُوذِنَهُ ‏ ‏فَنَهَانِي فَصَلَّيْنَا مَعَهُ رَكْعَةً وَقَضَيْنَا الَّتِي سُبِقْنَا بِهَا ‏","","",""],[17485,17485,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏عَبَّادِ بْنِ زِيَادٍ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ غَزَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏تَبُوكَ ‏ ‏قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏فَتَبَرَّزَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِبَلَ ‏ ‏الْغَائِطِ ‏ ‏فَحَمَلْتُ مَعَهُ ‏ ‏إِدَاوَةً ‏ ‏قَبْلَ صَلَاةِ الْفَجْرِ فَلَمَّا رَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيَّ أَخَذْتُ ‏ ‏أُهَرِيقُ ‏ ‏عَلَى يَدَيْهِ مِنْ ‏ ‏الْإِدَاوَةِ ‏ ‏وَغَسَلَ يَدَيْهِ ثَلَاثَ مِرَارٍ ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ يُخْرِجُ ‏ ‏جُبَّتَهُ ‏ ‏عَنْ ذِرَاعَيْهِ فَضَاقَ كُمَّا ‏ ‏جُبَّتِهِ ‏ ‏فَأَدْخَلَ يَدَيْهِ فِي ‏ ‏الْجُبَّةِ ‏ ‏حَتَّى أَخْرَجَ ذِرَاعَيْهِ مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏وَغَسَلَ ذِرَاعَيْهِ إِلَى الْمِرْفَقَيْنِ ثُمَّ مَسَحَ عَلَى ‏ ‏خُفَّيْهِ ‏ ‏ثُمَّ أَقْبَلَ قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏فَأَقْبَلْتُ مَعَهُ حَتَّى نَجِدَ النَّاسَ قَدْ قَدَّمُوا ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏يُصَلِّي بِهِمْ فَأَدْرَكَ إِحْدَى الرَّكْعَتَيْنِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏فَصَلَّى مَعَ النَّاسِ الرَّكْعَةَ الْآخِرَةَ ‏ ‏فَلَمَّا سَلَّمَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُتِمُّ صَلَاتَهُ فَأَفْزَعَ ذَلِكَ الْمُسْلِمِينَ فَأَكْثَرُوا التَّسْبِيحَ فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَهُ أَقْبَلَ عَلَيْهِمْ ثُمَّ قَالَ ‏ ‏أَحْسَنْتُمْ ‏ ‏أَوْ قَدْ أَصَبْتُمْ ‏ ‏يَغْبِطُهُمْ ‏ ‏أَنْ صَلَّوْا الصَّلَاةَ لِوَقْتِهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ الْمُغِيرَةِ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏عَبَّادٍ ‏ ‏قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏وَأَرَدْتُ تَأْخِيرَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُ ‏","","",""],[17486,17486,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فِي مَسِيرٍ فَقَالَ أَمَعَكَ مَاءٌ قُلْتُ نَعَمْ فَنَزَلَ عَنْ رَاحِلَتِهِ ثُمَّ مَشَى حَتَّى ‏ ‏تَوَارَى ‏ ‏عَنِّي فِي سَوَادِ اللَّيْلِ ثُمَّ جَاءَ فَأَفْرَغْتُ عَلَيْهِ مِنْ ‏ ‏الْإِدَاوَةِ ‏ ‏فَغَسَلَ وَجْهَهُ وَعَلَيْهِ ‏ ‏جُبَّةُ ‏ ‏صُوفٍ ضَيِّقَةُ الْكُمَّيْنِ فَلَمْ يَسْتَطِعْ أَنْ يُخْرِجَ ذِرَاعَيْهِ مِنْهَا فَأَخْرَجَهُمَا مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ ذِرَاعَيْهِ وَمَسَحَ بِرَأْسِهِ ثُمَّ أَهْوَيْتُ لِأَنْزِعَ ‏ ‏خُفَّيْهِ ‏ ‏فَقَالَ ‏ ‏دَعْهُمَا فَإِنِّي أَدْخَلْتُهُمَا طَاهِرَتَيْنِ فَمَسَحَ عَلَيْهِمَا ‏","","",""],[17487,17487,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْرٌ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ حَيْوَةَ ‏ ‏عَنْ ‏ ‏كَاتِبِ الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَسَحَ أَسْفَلَ ‏ ‏الْخُفِّ ‏ ‏وَأَعْلَاهُ ‏","","",""],[17488,17488,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏سَمِعَ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى تَوَرَّمَتْ قَدَمَاهُ فَقِيلَ لَهُ يَا رَسُولَ اللَّهِ قَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ فَقَالَ ‏ ‏أَوَلَا أَكُونُ عَبْدًا شَكُورًا ‏","","",""],[17489,17489,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدَةَ ‏ ‏وَعَبْدِ الْمَلِكِ ‏ ‏سَمِعَا ‏ ‏وَرَّادًا ‏ ‏كَتَبَ إِلَيْهِ ‏ ‏يَعْنِي ‏ ‏الْمُغِيرَةَ ‏ ‏كَتَبَ إِلَيْهِ ‏ ‏مُعَاوِيَةُ ‏ ‏اكْتُبْ إِلَيَّ بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَتَبَ ‏ ‏إِلَيْهِ ‏ ‏يَعْنِي ‏ ‏الْمُغِيرَةَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏","","",""],[17490,17490,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏الْعَقَّارِ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَمْ يَتَوَكَّلْ مَنْ ‏ ‏اسْتَرْقَى ‏ ‏وَاكْتَوَى ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّتَيْنِ ‏ ‏أَوْ اكْتَوَى ‏","","",""],[17491,17491,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَذْكُرُهُ عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَائِلٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏نَجْرَانَ ‏ ‏قَالَ فَقَالُوا أَرَأَيْتَ مَا تَقْرَءُونَ يَا أُخْتَ ‏ ‏هَارُونَ ‏ ‏وَمُوسَى ‏ ‏قَبْلَ ‏ ‏عِيسَى ‏ ‏بِكَذَا وَكَذَا قَالَ فَرَجَعْتُ فَذَكَرْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَلَا أَخْبَرْتَهُمْ أَنَّهُمْ كَانُوا يُسَمَّوْنَ بِالْأَنْبِيَاءِ وَالصَّالِحِينَ قَبْلَهُمْ ‏","","",""],[17492,17492,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏خَرَجَ يَوْمًا ‏ ‏فَرَقِيَ ‏ ‏عَلَى الْمِنْبَرِ فَحَمِدَ اللَّهَ ‏ ‏وَأَثْنَى ‏ ‏عَلَيْهِ ثُمَّ قَالَ مَا بَالُ هَذَا ‏ ‏النَّوْحِ ‏ ‏فِي الْإِسْلَامِ وَكَانَ مَاتَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَنِيحَ ‏ ‏عَلَيْهِ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ كَذِبًا عَلَيَّ لَيْسَ كَكَذِبٍ عَلَى أَحَدٍ فَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّهُ مَنْ ‏ ‏نِيحَ ‏ ‏عَلَيْهِ يُعَذَّبْ بِمَا ‏ ‏نِيحَ ‏ ‏عَلَيْهِ ‏","","",""],[17493,17493,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَنْ يَزَالَ أُنَاسٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى النَّاسِ حَتَّى يَأْتِيَهُمْ أَمْرُ اللَّهِ وَهُمْ ظَاهِرُونَ ‏","","",""],[17494,17494,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏مَا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدَّجَّالِ ‏ ‏أَحَدٌ أَكْثَرَ مِمَّا سَأَلْتُهُ وَإِنَّهُ قَالَ لِي مَا يَضُرُّكَ مِنْهُ قَالَ قُلْتُ إِنَّهُمْ يَقُولُونَ إِنَّ مَعَهُ جَبَلَ خُبْزٍ وَنَهْرَ مَاءٍ قَالَ ‏ ‏هُوَ أَهْوَنُ عَلَى اللَّهِ مِنْ ذَاكَ ‏","","",""],[17495,17495,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏أَكَلْتُ ثُومًا ثُمَّ أَتَيْتُ مُصَلَّى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْتُهُ قَدْ سَبَقَنِي بِرَكْعَةٍ فَلَمَّا صَلَّى قُمْتُ أَقْضِي فَوَجَدَ رِيحَ الثُّومِ فَقَالَ ‏ ‏مَنْ أَكَلَ هَذِهِ الْبَقْلَةَ فَلَا يَقْرَبَنَّ مَسْجِدَنَا حَتَّى يَذْهَبَ رِيحُهَا قَالَ فَلَمَّا قَضَيْتُ الصَّلَاةَ أَتَيْتُهُ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ لِي عُذْرًا نَاوِلْنِي يَدَكَ قَالَ فَوَجَدْتُهُ وَاللَّهِ سَهْلًا فَنَاوَلَنِي يَدَهُ فَأَدْخَلْتُهَا فِي كُمِّي إِلَى صَدْرِي فَوَجَدَهُ ‏ ‏مَعْصُوبًا ‏ ‏فَقَالَ إِنَّ لَكَ عُذْرًا ‏","","",""],[17496,17496,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنْ ‏ ‏هُذَيْلِ بْنِ شُرَحْبِيلَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ ‏","","",""],[17497,17497,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ اللَّهِ الثَّقَفِيُّ ‏ ‏قَالَ ‏ ‏رَوْحُ ‏ ‏بْنُ جُبَيْرِ بْنِ حَيَّةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏زِيَادُ بْنُ جُبَيْرٍ ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ جُبَيْرِ بْنِ حَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّاكِبُ خَلْفَ الْجِنَازَةِ وَالْمَاشِي حَيْثُ شَاءَ مِنْهَا وَالطِّفْلُ يُصَلَّى عَلَيْهِ ‏","","",""],[17498,17498,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ سَبِّ الْأَمْوَاتِ ‏","","",""],[17499,17499,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا الْأَمْوَاتَ فَتُؤْذُوا الْأَحْيَاءَ ‏","","",""],[17500,17500,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏عِنْدَ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا الْأَمْوَاتَ فَتُؤْذُوا الْأَحْيَاءَ ‏","","",""],[17501,17501,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَشُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَبِي شَبِيبٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَدَّثَ بِحَدِيثٍ وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَذَّابِينَ ‏","","",""],[17502,17502,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏أَبِي صَخْرَةَ جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏ضِفْتُ ‏ ‏بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ ‏ ‏فَأَمَرَ ‏ ‏بِجَنْبٍ ‏ ‏فَشُوِيَ قَالَ فَأَخَذَ ‏ ‏الشَّفْرَةَ ‏ ‏فَجَعَلَ ‏ ‏يَحُزُّ ‏ ‏لِي بِهَا مِنْهُ قَالَ فَجَاءَهُ ‏ ‏بِلَالٌ ‏ ‏يُؤْذِنُهُ بِالصَّلَاةِ فَأَلْقَى ‏ ‏الشَّفْرَةَ ‏ ‏وَقَالَ مَا لَهُ تَرِبَتْ يَدَاهُ قَالَ ‏ ‏مُغِيرَةُ ‏ ‏وَكَانَ شَارِبِي وَفَى فَقَصَّهُ لِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى سِوَاكٍ ‏ ‏أَوْ قَالَ أَقُصُّهُ لَكَ عَلَى سِوَاكٍ ‏","","",""],[17503,17503,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْمِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏قَالَ ‏ ‏اسْتَشَارَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏النَّاسَ فِي ‏ ‏مِلَاصِ ‏ ‏الْمَرْأَةِ قَالَ فَقَالَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى فِيهِ ‏ ‏بِغُرَّةٍ ‏ ‏عَبْدٍ أَوْ ‏ ‏أَمَّةٍ ‏ ‏قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏ائْتِنِي بِمَنْ يَشْهَدُ مَعَكَ قَالَ فَشَهِدَ لَهُ ‏ ‏مُحَمَّدُ بْنُ مَسْلَمَةَ ‏","","",""],[17504,17504,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏طَعْمَةُ بْنُ عَمْرٍو الْجَعْفَرِيُّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ بَيَانٍ التَّغْلِبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَاعَ الْخَمْرَ ‏ ‏فَلْيُشَقِّصْ ‏ ‏الْخَنَازِيرَ ‏ ‏يَعْنِي ‏ ‏يُقَصِّبُهَا ‏","","",""],[17505,17505,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عُقْبَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ ‏ ‏بِحُجْزَةِ ‏ ‏سُفْيَانَ بْنِ سَهْلٍ الثَّقَفِيِّ ‏ ‏فَقَالَ يَا ‏ ‏سُفْيَانُ ‏ ‏لَا ‏ ‏تُسْبِلْ ‏ ‏إِزَارَكَ ‏ ‏فَإِنَّ اللَّهَ لَا يُحِبُّ ‏ ‏الْمُسْبِلِينَ ‏","","",""],[17506,17506,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَهَضَ فِي الرَّكْعَتَيْنِ فَسَبَّحْنَا بِهِ فَمَضَى فَلَمَّا أَتَمَّ الصَّلَاةَ سَجَدَ سَجْدَتَيْ السَّهْوِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً فَسَبَّحَ بِهِ مَنْ خَلْفَهُ فَأَشَارَ أَنْ قُومُوا ‏","","",""],[17507,17507,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ قَالَ ‏ ‏حَدَّثَنِي ‏ ‏عَقَّارُ بْنُ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏حَدِيثًا فَلَمَّا خَرَجْتُ مِنْ عِنْدِهِ لَمْ أُمْعِنْ حِفْظَهُ فَرَجَعْتُ إِلَيْهِ أَنَا وَصَاحِبٌ لِي فَلَقِيتُ ‏ ‏حَسَّانَ بْنَ أَبِي وَجْزَةَ ‏ ‏وَقَدْ خَرَجَ مِنْ عِنْدِهِ فَقَالَ مَا جَاءَ بِكَ فَقُلْتُ كَذَا وَكَذَا ‏ ‏فَقَالَ ‏ ‏حَسَّانُ ‏ ‏حَدَّثَنَاهُ ‏ ‏عَقَّارٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَمْ يَتَوَكَّلْ مَنْ اكْتَوَى ‏ ‏وَاسْتَرْقَى ‏","","",""],[17508,17508,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ مَاتَ ‏ ‏إِبْرَاهِيمُ ‏ ‏فَقَالَ النَّاسُ كَسَفَتْ لِمَوْتِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَةٌ مِنْ آيَاتِ اللَّهِ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا رَأَيْتُمْ ذَلِكَ فَصَلُّوا وَادْعُوا اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[17509,17509,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏إِيَادٌ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ سَرْحَانَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ طَعَامًا ثُمَّ أُقِيمَتْ الصَّلَاةُ فَقَامَ وَقَدْ كَانَ تَوَضَّأَ قَبْلَ ذَلِكَ فَأَتَيْتُهُ بِمَاءٍ لِيَتَوَضَّأَ مِنْهُ فَانْتَهَرَنِي وَقَالَ وَرَاءَكَ فَسَاءَنِي وَاللَّهِ ذَلِكَ ثُمَّ صَلَّى فَشَكَوْتُ ذَلِكَ إِلَى ‏ ‏عُمَرَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ إِنَّ ‏ ‏الْمُغِيرَةَ ‏ ‏قَدْ شَقَّ عَلَيْهِ انْتِهَارُكَ إِيَّاهُ وَخَشِيَ أَنْ يَكُونَ فِي نَفْسِكَ عَلَيْهِ شَيْءٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ عَلَيْهِ فِي نَفْسِي شَيْءٌ إِلَّا خَيْرٌ وَلَكِنْ أَتَانِي بِمَاءٍ لِأَتَوَضَّأَ وَإِنَّمَا أَكَلْتُ طَعَامًا وَلَوْ فَعَلْتُهُ فَعَلَ ذَلِكَ النَّاسُ بَعْدِي ‏","","",""],[17510,17510,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ عَامِرٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نُعْمٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَقَضَى ‏ ‏حَاجَتَهُ ‏ ‏ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى ‏ ‏خُفَّيْهِ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ نَسِيتَ قَالَ بَلْ أَنْتَ نَسِيتَ بِهَذَا أَمَرَنِي رَبِّي عَزَّ وَجَلَّ ‏","","",""],[17511,17511,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَقَّارِ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اكْتَوَى أَوْ ‏ ‏اسْتَرْقَى ‏ ‏فَقَدْ بَرِئَ مِنْ ‏ ‏التَّوَكُّلِ ‏","","",""],[17512,17512,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏أَمَّنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الظُّهْرِ ‏ ‏أَوْ الْعَصْرِ ‏ ‏فَقَامَ فَقُلْنَا سُبْحَانَ اللَّهِ فَقَالَ سُبْحَانَ اللَّهِ وَأَشَارَ بِيَدِهِ ‏ ‏يَعْنِي قُومُوا ‏ ‏فَقُمْنَا فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ سَجَدَ سَجْدَتَيْنِ ثُمَّ قَالَ ‏ ‏إِذَا ذَكَرَ أَحَدُكُمْ قَبْلَ أَنْ ‏ ‏يَسْتَتِمَّ ‏ ‏قَائِمًا فَلْيَجْلِسْ وَإِذَا ‏ ‏اسْتَتَمَّ ‏ ‏قَائِمًا فَلَا يَجْلِسْ ‏","","",""],[17513,17513,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ فَلَمْ يَسْتَتِمَّ قَائِمًا فَلْيَجْلِسْ وَإِذَا اسْتَتَمَّ قَائِمًا فَلَا يَجْلِسْ وَيَسْجُدُ سَجْدَتَيْ السَّهْوِ ‏","","",""],[17514,17514,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ يَعْنِي ابْنَ هَاشِمٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ إِبْرَاهِيمَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقَامًا ‏ ‏فَأَخْبَرَنَا بِمَا يَكُونُ فِي أُمَّتِهِ إِلَى يَوْمِ الْقِيَامَةِ وَعَاهُ مَنْ وَعَاهُ وَنَسِيَهُ مَنْ نَسِيَهُ ‏","","",""],[17515,17515,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَاءٍ فَأَتَيْتُ ‏ ‏خِبَاءً ‏ ‏فَإِذَا فِيهِ امْرَأَةٌ أَعْرَابِيَّةٌ قَالَ فَقُلْتُ إِنَّ هَذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُرِيدُ مَاءً يَتَوَضَّأُ فَهَلْ عِنْدَكِ مِنْ مَاءٍ قَالَتْ بِأَبِي وَأُمِّي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَاللَّهِ مَا تُظِلُّ السَّمَاءُ وَلَا تُقِلُّ الْأَرْضُ رُوحًا أَحَبَّ إِلَيَّ مِنْ رُوحِهِ وَلَا أَعَزَّ وَلَكِنَّ هَذِهِ ‏ ‏الْقِرْبَةَ ‏ ‏مَسْكُ ‏ ‏مَيْتَةٍ ‏ ‏وَلَا أُحِبُّ أُنَجِّسُ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَجَعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ فَقَالَ ارْجِعْ إِلَيْهَا ‏ ‏فَإِنْ كَانَتْ ‏ ‏دَبَغَتْهُ ‏ ‏فَهِيَ طَهُورُهَا قَالَ فَرَجَعْتُ إِلَيْهَا فَذَكَرْتُ ذَلِكَ لَهَا فَقَالَتْ أَيْ وَاللَّهِ لَقَدْ ‏ ‏دَبَغْتُهَا ‏ ‏فَأَتَيْتُهُ بِمَاءٍ مِنْهَا وَعَلَيْهِ يَوْمَئِذٍ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ ‏ ‏وَعَلَيْهِ خُفَّانِ وَخِمَارٌ قَالَ فَأَدْخَلَ يَدَيْهِ مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏قَالَ مِنْ ضِيقِ كُمَّيْهَا قَالَ فَتَوَضَّأَ فَمَسَحَ عَلَى ‏ ‏الْخِمَارِ ‏ ‏وَالْخُفَّيْنِ ‏","","",""],[17516,17516,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏ذَهَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِبَعْضِ ‏ ‏حَاجَتِهِ ‏ ‏ثُمَّ جَاءَ فَسَكَبْتُ عَلَيْهِ الْمَاءَ ‏ ‏فَغَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ يَغْسِلُ ذِرَاعَيْهِ فَضَاقَ عَنْهُمَا كُمُّ ‏ ‏الْجُبَّةِ ‏ ‏فَأَخْرَجَهُمَا مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَهُمَا ثُمَّ مَسَحَ عَلَى ‏ ‏خُفَّيْهِ ‏","","",""],[17517,17517,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَبِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ الْحَارِثِ الطَّائِفِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَوْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏ ‏أَوْ يَسْتَحِبُّ أَنْ يُصَلِّيَ ‏ ‏عَلَى فَرْوَةٍ ‏ ‏مَدْبُوغَةٍ ‏","","",""],[17518,17518,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏قَالَ قَالَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى ظُهُورِ ‏ ‏الْخُفَّيْنِ ‏ ‏حَدَّثَنَاه ‏ ‏سُرَيْجٌ ‏ ‏والْهَاشِمِيُّ ‏ ‏أَيْضًا ‏","","",""],[17519,17519,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏شَرِيكٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا السَّائِبِ ‏ ‏مَوْلَى ‏ ‏هِشَامِ بْنِ زُهْرَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏يَقُولُ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَنَزَلَ مَنْزِلًا ‏ ‏فَتَبَرَّزَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَبِعْتُهُ ‏ ‏بِإِدَاوَةٍ ‏ ‏فَصَبَبْتُ عَلَيْهِ فَتَوَضَّأَ وَمَسَحَ عَلَى ‏ ‏الْخُفَّيْنِ ‏","","",""],[17520,17520,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏مَوْلَى ‏ ‏الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَقِيلَ وَقَالَ وَمَنْعَ ‏ ‏وَهَاتِ ‏ ‏وَوَأْدَ ‏ ‏الْبَنَاتِ ‏ ‏وَعُقُوقَ ‏ ‏الْأُمَّهَاتِ وَإِضَاعَةَ الْمَالِ ‏","","",""],[17521,17521,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ الْجُعْفِيِّ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏قَالَ سَمِعْتُهُ يُحَدِّثُ عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّهُ ‏ ‏قَامَ فِي الرَّكْعَتَيْنِ فَسَبَّحَ الْقَوْمُ قَالَ ‏ ‏فَأُرَاهُ فَسَبَّحَ وَمَضَى ‏ ‏ثُمَّ سَجَدَ سَجْدَتَيْنِ بَعْدَمَا سَلَّمَ فَقَالَ هَكَذَا فَعَلْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا شَكَّ فِي سَبَّحَ ‏","","",""],[17522,17522,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ شِبْلٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏كَاتِبِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏مُعَاوِيَةُ ‏ ‏إِلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏اكْتُبْ إِلَيَّ بِمَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَانِي ‏ ‏الْمُغِيرَةُ ‏ ‏قَالَ فَكَتَبَ إِلَيْهِ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا انْصَرَفَ مِنْ الصَّلَاةِ قَالَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏","","",""],[17523,17523,"","","‏ ‏وَسَمِعْتُهُ ‏ ‏يَنْهَى عَنْ قِيلَ وَقَالَ وَعَنْ كَثْرَةِ السُّؤَالِ وَإِضَاعَةِ الْمَالِ وَعَنْ ‏ ‏وَأْدِ ‏ ‏الْبَنَاتِ ‏ ‏وَعُقُوقِ ‏ ‏الْأُمَّهَاتِ وَمَنْعٍ ‏ ‏وَهَاتِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَنْبَأَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدَةَ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا سَلَّمَ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ مِثْلَ حَدِيثِ ‏ ‏الْمُغِيرَةِ ‏ ‏إِلَّا أَنَّهُ لَمْ يَذْكُرْ ‏ ‏وَأْدَ ‏ ‏الْبَنَاتِ ‏","","",""],[17524,17524,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَسَحَ بِنَاصِيَتِهِ وَمَسَحَ عَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏وَالْعِمَامَةِ ‏ ‏قَالَ ‏ ‏بَكْرٌ ‏ ‏وَقَدْ سَمِعْتُهُ مِنْ ‏ ‏ابْنِ الْمُغِيرَةِ ‏","","",""],[17525,17525,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فِي مَسِيرٍ فَقَالَ لِي مَعَكَ مَاءٌ قُلْتُ نَعَمْ فَنَزَلَ عَنْ ‏ ‏رَاحِلَتِهِ ‏ ‏ثُمَّ ذَهَبَ عَنِّي حَتَّى ‏ ‏تَوَارَى ‏ ‏عَنِّي فِي سَوَادِ اللَّيْلِ قَالَ وَكَانَتْ عَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏فَذَهَبَ يُخْرِجُ يَدَيْهِ فَلَمْ يَسْتَطِعْ أَنْ يُخْرِجَ يَدَيْهِ مِنْهَا فَأَخْرَجَ يَدَيْهِ مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ يَدَيْهِ وَمَسَحَ بِرَأْسِهِ ثُمَّ ذَهَبْتُ أَنْزِعُ خُفَّيْهِ قَالَ دَعْهُمَا فَإِنِّي أَدْخَلْتُهُمَا وَهُمَا طَاهِرَتَانِ فَمَسَحَ عَلَيْهِمَا ‏","","",""],[17526,17526,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏أَبِي صَخْرَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏بِتُّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ ‏ ‏فَأَمَرَ بِجَنْبٍ فَشُوِيَ ثُمَّ أَخَذَ ‏ ‏الشَّفْرَةَ ‏ ‏فَجَعَلَ ‏ ‏يَحُزُّ ‏ ‏لِي بِهَا مِنْهُ فَجَاءَ ‏ ‏بِلَالٌ ‏ ‏يُؤْذِنُهُ بِالصَّلَاةِ فَأَلْقَى ‏ ‏الشَّفْرَةَ ‏ ‏وَقَالَ مَا لَهُ ‏ ‏تَرِبَتْ ‏ ‏يَدَاهُ قَالَ وَكَانَ شَارِبِي وَفَى فَقَصَّهُ لِي عَلَى سِوَاكٍ ‏ ‏أَوْ قَالَ أَقُصُّهُ لَكَ عَلَى سِوَاكٍ ‏","","",""],[17527,17527,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُبَيْدٍ الطَّائِيُّ ‏ ‏وَمُحَمَّدُ بْنُ قَيْسٍ الْأَسَدِيُّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبِيعَةَ الْوَالِبِيِّ ‏ ‏قَالَ ‏ ‏إِنَّ أَوَّلَ مِنْ ‏ ‏نِيحَ ‏ ‏عَلَيْهِ ‏ ‏بِالْكُوفَةِ ‏ ‏قَرَظَةُ بْنُ كَعْبٍ الْأَنْصَارِيُّ ‏ ‏فَقَالَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏نِيحَ ‏ ‏عَلَيْهِ فَإِنَّهُ يُعَذَّبُ بِمَا ‏ ‏نِيحَ ‏ ‏عَلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[17528,17528,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏وَسُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي حَتَّى تَرِمَ قَدَمَاهُ فَقِيلَ لَهُ فَقَالَ ‏ ‏أَوَلَا أَكُونُ عَبْدًا شَكُورًا ‏","","",""],[17529,17529,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبِسَ ‏ ‏جُبَّةً ‏ ‏رُومِيَّةً ضَيِّقَةَ الْكُمَّيْنِ ‏","","",""],[17530,17530,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَبِي شَبِيبٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَدَّثَ بِحَدِيثٍ وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبِينَ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَهُوَ أَحَدُ الْكَذَّابِينَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏فَذَكَرَ نَحْوَهُ قَالَ فَهُوَ أَحَدُ الْكَاذِبِينَ ‏","","",""],[17531,17531,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ ‏ ‏سَمِعْتُهُ مِنَ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ شَهِدَ لِي ‏ ‏عُرْوَةُ بْنُ الْمُغِيرَةِ ‏ ‏عَلَى ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ شَهِدَ لَهُ أَبُوهُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ فِي سَفَرٍ ‏ ‏فَأَنَاخَ ‏ ‏وَأَنَاخَ ‏ ‏أَصْحَابُهُ قَالَ ‏ ‏فَبَرَزَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ ثُمَّ جَاءَ فَأَتَيْتُهُ ‏ ‏بِإِدَاوَةٍ ‏ ‏وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏لَهُ رُومِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ فَذَهَبَ يُخْرِجُ يَدَيْهِ فَضَاقَتَا فَأَخْرَجَهُمَا مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏قَالَ ثُمَّ صَبَبْتُ عَلَيْهِ فَتَوَضَّأَ فَلَمَّا بَلَغَ ‏ ‏الْخُفَّيْنِ ‏ ‏أَهْوَيْتُ لِأَنْزِعَهُمَا فَقَالَ لَا إِنِّي أَدْخَلْتُهُمَا وَهُمَا طَاهِرَتَانِ قَالَ فَتَوَضَّأَ وَمَسَحَ عَلَيْهِمَا ‏ ‏قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏فَشَهِدَ لِي ‏ ‏عُرْوَةُ ‏ ‏عَلَى أَبِيهِ شَهِدَ لَهُ أَبُوهُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17532,17532,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي حَتَّى تَرِمَ قَدَمَاهُ فَقِيلَ لَهُ أَلَيْسَ قَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ قَالَ أَفَلَا أَكُونُ عَبْدًا شَكُورًا ‏","","",""],[17533,17533,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ طَرَفَةَ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى خَيْرًا مِنْهَا فَلْيَأْتِ بِالَّذِي هُوَ خَيْرٌ ‏","","",""],[17534,17534,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَامِرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَيْدِ ‏ ‏الْمِعْرَاضِ ‏ ‏فَقَالَ مَا أَصَبْتَ بِحَدِّهِ فَكُلْهُ وَمَا أَصَبْتَ ‏ ‏بِعَرْضِهِ ‏ ‏فَهُوَ وَقِيذٌ وَسَأَلْتُهُ عَنْ صَيْدِ الْكَلْبِ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏إِذَا أَرْسَلْتَ كَلْبَكَ وَذَكَرْتَ اسْمَ اللَّهِ فَكُلْ ‏ ‏فَقَالَ وَمَا أَمْسَكَ عَلَيْكَ وَلَمْ يَأْكُلْ فَكُلْهُ فَإِنَّ أَخْذَهُ ‏ ‏ذَكَاتُهُ ‏ ‏وَإِنْ وَجَدْتَ مَعَ كَلْبِكَ كَلْبًا آخَرَ فَخَشِيتَ أَنْ يَكُونَ أَخَذَهُ مَعَهُ وَقَدْ قَتَلَهُ فَلَا تَأْكُلْ فَإِنَّكَ إِنَّمَا ذَكَرْتَ اسْمَ اللَّهِ عَلَى كَلْبِكَ وَلَمْ تَذْكُرْهُ عَلَى غَيْرِهِ ‏","","",""],[17535,17535,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ الطَّائِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا سَيُكَلِّمُهُ رَبُّهُ عَزَّ وَجَلَّ لَيْسَ بَيْنَهُ وَبَيْنَهُ تُرْجُمَانٌ فَيَنْظُرُ عَمَّنْ أَيْمَنَ مِنْهُ فَلَا يَرَى إِلَّا شَيْئًا قَدَّمَهُ وَيَنْظُرُ عَمَّنْ أَشْأَمَ مِنْهُ فَلَا يَرَى إِلَّا شَيْئًا قَدَّمَهُ وَيَنْظُرُ أَمَامَهُ فَتَسْتَقْبِلُهُ النَّارُ فَمَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَتَّقِيَ النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ فَلْيَفْعَلْ ‏","","",""],[17536,17536,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ يَعْنِي ابْنَ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ طَرَفَةَ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏أَنَّ رَجُلًا خَطَبَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَنْ يُطِعْ اللَّهَ وَرَسُولَهُ فَقَدْ رَشَدَ وَمَنْ يَعْصِهِمَا فَقَدْ ‏ ‏غَوَى ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِئْسَ الْخَطِيبُ أَنْتَ قُلْ وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ ‏","","",""],[17537,17537,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدَانُ الْجُهَنِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ خَلِيفَةَ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَتَّقِيَ النَّارَ فَلْيَتَصَدَّقْ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ فَمَنْ لَمْ يَجِدْ فَبِكَلِمَةٍ طَيِّبَةٍ ‏","","",""],[17538,17538,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَيْدِ ‏ ‏الْمِعْرَاضِ ‏ ‏فَقَالَ ‏ ‏لَا تَأْكُلْ إِلَّا أَنْ ‏ ‏يَخْزِقَ ‏","","",""],[17539,17539,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُرَيِّ بْنِ قَطَرِيٍّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ الطَّائِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا نَصِيدُ الصَّيْدَ فَلَا نَجِدُ سِكِّينًا إِلَّا ‏ ‏الظِّرَارَ ‏ ‏وَشِقَّةَ الْعَصَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَّ الدَّمَ بِمَا شِئْتَ وَاذْكُرْ اسْمَ اللَّهِ ‏","","",""],[17540,17540,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيَأْتِ الَّذِي هُوَ خَيْرٌ وَلْيُكَفِّرْ عَنْ يَمِينِهِ ‏","","",""],[17541,17541,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَتَّقِيَ النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ فَلْيَفْعَلْ ‏","","",""],[17542,17542,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّارَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَتَعَوَّذَ مِنْهَا ‏ ‏وَأَشَاحَ ‏ ‏بِوَجْهِهِ ‏ ‏ثُمَّ قَالَ ‏ ‏اتَّقُوا النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ فَإِنْ لَمْ تَجِدُوا فَبِكَلِمَةٍ طَيِّبَةٍ ‏","","",""],[17543,17543,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحِلِّ بْنِ خَلِيفَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَدِيَّ بْنَ حَاتِمٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ فَإِنْ لَمْ تَجِدُوا فَبِكَلِمَةٍ طَيِّبَةٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَبِكَلِمَةٍ ‏","","",""],[17544,17544,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ مَسْرُوقٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الشَّعْبِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَدِيَّ بْنَ حَاتِمٍ ‏ ‏وَكَانَ لَنَا جَارًا أَوْ دَخِيلًا وَرَبِيطًا بِالنَّهْرَيْنِ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أُرْسِلُ كَلْبِي فَأَجِدُ مَعَ كَلْبِي كَلْبًا قَدْ أَخَذَ لَا أَدْرِي أَيُّهُمَا أَخَذَ قَالَ ‏ ‏فَلَا تَأْكُلْ فَإِنَّمَا سَمَّيْتَ عَلَى كَلْبِكَ ‏ ‏وَلَمْ تُسَمِّ عَلَى غَيْرِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[17545,17545,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْعَزِيزِ بْنُ رُفَيْعٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏تَمِيمَ بْنَ طَرَفَةَ الطَّائِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيَأْتِ الَّذِي هُوَ خَيْرٌ وَلْيَتْرُكْ يَمِينَهُ ‏","","",""],[17546,17546,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَّمَنِي الْإِسْلَامَ ‏ ‏وَنَعَتَ ‏ ‏لِي الصَّلَاةَ وَكَيْفَ أُصَلِّي كُلَّ صَلَاةٍ لِوَقْتِهَا ثُمَّ قَالَ لِي كَيْفَ أَنْتَ يَا ‏ ‏ابْنَ حَاتِمٍ ‏ ‏إِذَا رَكِبْتَ مِنْ قُصُورِ ‏ ‏الْيَمَنِ ‏ ‏لَا تَخَافُ إِلَّا اللَّهَ حَتَّى تَنْزِلَ قُصُورَ ‏ ‏الْحِيرَةِ ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ فَأَيْنَ مَقَانِبُ ‏ ‏طَيِّئٍ ‏ ‏وَرِجَالُهَا قَالَ يَكْفِيكَ اللَّهُ ‏ ‏طَيِّئًا ‏ ‏وَمَنْ سِوَاهَا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّا قَوْمٌ نَتَصَيَّدُ بِهَذِهِ الْكِلَابِ ‏ ‏وَالْبَزَاةِ ‏ ‏فَمَا يَحِلُّ لَنَا مِنْهَا قَالَ يَحِلُّ لَكُمْ ‏ { ‏مَا عَلَّمْتُمْ مِنْ الْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمْ اللَّهُ فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهِ ‏} ‏فَمَا عَلَّمْتَ مِنْ كَلْبٍ ‏ ‏أَوْ ‏ ‏بَازٍ ‏ ‏ثُمَّ أَرْسَلْتَ وَذَكَرْتَ اسْمَ اللَّهِ عَلَيْهِ فَكُلْ مِمَّا ‏ ‏أَمْسَكَ ‏ ‏عَلَيْكَ قُلْتُ وَإِنْ قَتَلَ قَالَ وَإِنْ قَتَلَ وَلَمْ يَأْكُلْ مِنْهُ شَيْئًا فَإِنَّمَا أَمْسَكَهُ عَلَيْكَ قُلْتُ أَفَرَأَيْتَ إِنْ خَالَطَ كِلَابَنَا كِلَابٌ أُخْرَى حِينَ نُرْسِلُهَا قَالَ لَا تَأْكُلْ حَتَّى تَعْلَمَ أَنَّ كَلْبَكَ هُوَ الَّذِي أَمْسَكَ عَلَيْكَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّا قَوْمٌ نَرْمِي بِالْمِعْرَاضِ فَمَا يَحِلُّ لَنَا قَالَ لَا تَأْكُلْ مَا ‏ ‏أَصَبْتَ ‏ ‏بِالْمِعْرَاضِ ‏ ‏إِلَّا مَا ‏ ‏ذَكَّيْتَ ‏","","",""],[17547,17547,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أَرْضِي أَرْضُ صَيْدٍ قَالَ ‏ ‏إِذَا أَرْسَلْتَ كَلْبَكَ وَسَمَّيْتَ فَكُلْ مَا ‏ ‏أَمْسَكَ ‏ ‏عَلَيْكَ كَلْبُكَ وَإِنْ قَتَلَ فَإِنْ أَكَلَ مِنْهُ فَلَا تَأْكُلْ فَإِنَّهُ إِنَّمَا ‏ ‏أَمْسَكَ ‏ ‏عَلَى نَفْسِهِ وَإِذَا أَرْسَلْتَ كَلْبَكَ فَخَالَطَتْهُ أَكْلُبٌ لَمْ تُسَمِّ عَلَيْهَا فَلَا تَأْكُلْ فَإِنَّكَ لَا تَدْرِي أَيُّهَا قَتَلَهُ ‏","","",""],[17548,17548,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَدِيِّ بْنِ حَاتِمٍ ‏ ‏حَدِيثٌ بَلَغَنِي عَنْكَ أُحِبُّ أَنْ أَسْمَعَهُ مِنْكَ قَالَ نَعَمْ لَمَّا بَلَغَنِي خُرُوجُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَرِهْتُ خُرُوجَهُ كَرَاهَةً شَدِيدَةً خَرَجْتُ حَتَّى وَقَعْتُ نَاحِيَةَ ‏ ‏الرُّومِ ‏ ‏وَقَالَ ‏ ‏يَعْنِي ‏ ‏يَزِيدَ ‏ ‏بِبَغْدَادَ ‏ ‏حَتَّى قَدِمْتُ عَلَى ‏ ‏قَيْصَرَ ‏ ‏قَالَ فَكَرِهْتُ مَكَانِي ذَلِكَ أَشَدَّ مِنْ كَرَاهِيَتِي لِخُرُوجِهِ قَالَ فَقُلْتُ وَاللَّهِ لَوْلَا أَتَيْتُ هَذَا الرَّجُلَ فَإِنْ كَانَ كَاذِبًا لَمْ يَضُرَّنِي وَإِنْ كَانَ صَادِقًا عَلِمْتُ قَالَ فَقَدِمْتُ فَأَتَيْتُهُ فَلَمَّا قَدِمْتُ قَالَ النَّاسُ ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏قَالَ فَدَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي يَا ‏ ‏عَدِيُّ بْنَ حَاتِمٍ ‏ ‏أَسْلِمْ تَسْلَمْ ثَلَاثًا قَالَ قُلْتُ إِنِّي عَلَى دِينٍ قَالَ أَنَا أَعْلَمُ بِدِينِكَ مِنْكَ فَقُلْتُ أَنْتَ أَعْلَمُ بِدِينِي مِنِّي قَالَ نَعَمْ أَلَسْتَ مِنْ ‏ ‏الرَّكُوسِيَّةِ ‏ ‏وَأَنْتَ تَأْكُلُ ‏ ‏مِرْبَاعَ ‏ ‏قَوْمِكَ قُلْتُ بَلَى قَالَ فَإِنَّ هَذَا لَا يَحِلُّ لَكَ فِي دِينِكَ قَالَ فَلَمْ يَعْدُ أَنْ قَالَهَا فَتَوَاضَعْتُ لَهَا فَقَالَ أَمَا إِنِّي أَعْلَمُ مَا الَّذِي يَمْنَعُكَ مِنْ الْإِسْلَامِ تَقُولُ إِنَّمَا اتَّبَعَهُ ضَعَفَةُ النَّاسِ وَمَنْ لَا قُوَّةَ لَهُ وَقَدْ رَمَتْهُمْ ‏ ‏الْعَرَبُ ‏ ‏أَتَعْرِفُ ‏ ‏الْحِيرَةَ ‏ ‏قُلْتُ لَمْ أَرَهَا وَقَدْ سَمِعْتُ بِهَا قَالَ فَوَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيُتِمَّنَّ اللَّهُ هَذَا الْأَمْرَ حَتَّى تَخْرُجَ ‏ ‏الظَّعِينَةُ ‏ ‏مِنْ ‏ ‏الْحِيرَةِ ‏ ‏حَتَّى تَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏فِي غَيْرِ جِوَارِ أَحَدٍ وَلَيَفْتَحَنَّ كُنُوزَ ‏ ‏كِسْرَى بْنِ هُرْمُزَ ‏ ‏قَالَ قُلْتُ ‏ ‏كِسْرَى بْنُ هُرْمُزَ ‏ ‏قَالَ نَعَمْ ‏ ‏كِسْرَى بْنُ هُرْمُزَ ‏ ‏وَلَيُبْذَلَنَّ الْمَالُ حَتَّى لَا يَقْبَلَهُ أَحَدٌ قَالَ ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏فَهَذِهِ ‏ ‏الظَّعِينَةُ ‏ ‏تَخْرُجُ مِنْ ‏ ‏الْحِيرَةِ ‏ ‏فَتَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏فِي غَيْرِ ‏ ‏جِوَارٍ ‏ ‏وَلَقَدْ كُنْتُ فِيمَنْ فَتَحَ كُنُوزَ ‏ ‏كِسْرَى بْنِ هُرْمُزَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ لَتَكُونَنَّ الثَّالِثَةُ لِأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ قَالَهَا ‏","","",""],[17549,17549,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْوَلِيدِ بْنِ الْمُسَيَّرِ الطَّائِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحِلٌّ الطَّائِيُّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏مَنْ أَمَّنَا فَلْيُتِمَّ ‏ ‏الرُّكُوعَ وَالسُّجُودَ فَإِنَّ فِينَا الضَّعِيفَ وَالْكَبِيرَ وَالْمَرِيضَ وَالْعَابِرَ سَبِيلٍ وَذَا الْحَاجَةِ هَكَذَا كُنَّا نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17550,17550,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُرَيَّ بْنَ قَطَرِيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَدِىَّ بْنَ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أَبِي كَانَ يَصِلُ الرَّحِمَ وَيَفْعَلُ كَذَا وَكَذَا قَالَ إِنَّ أَبَاكَ أَرَادَ أَمْرًا فَأَدْرَكَهُ ‏ ‏يَعْنِي الذِّكْرَ قَالَ قُلْتُ إِنِّي أَسْأَلُكَ عَنْ طَعَامٍ لَا أَدَعُهُ إِلَّا تَحَرُّجًا قَالَ لَا تَدَعْ شَيْئًا ‏ ‏ضَارَعْتَ ‏ ‏فِيهِ نَصْرَانِيَّةً قُلْتُ أُرْسِلُ كَلْبِي فَيَأْخُذُ الصَّيْدَ وَلَيْسَ مَعِي مَا ‏ ‏أُذَكِّيهِ ‏ ‏بِهِ فَأَذْبَحَهُ ‏ ‏بِالْمَرْوَةِ ‏ ‏وَالْعَصَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَّ الدَّمَ بِمَا شِئْتَ وَاذْكُرْ اسْمَ اللَّهِ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ إِلَّا أَنَّهُ قَالَ سَمِعْتُ ‏ ‏مُرَيَّ بْنَ قَطَرِيٍّ الطَّائِيَّ ‏ ‏وَقَالَ إِنَّ أَبَاكَ أَرَادَ أَمْرًا فَأَدْرَكَهُ قَالَ ‏ ‏سِمَاكٌ ‏ ‏يَعْنِي الذِّكْرَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏فَذَكَرَهُ مِنْ مَوْضِعِ الصَّيْدِ وَقَالَ أَمْرِرْ الدَّمَ ‏","","",""],[17551,17551,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ طَرَفَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عَدِيَّ بْنَ حَاتِمٍ ‏ ‏وَأَتَاهُ رَجُلٌ يَسْأَلُهُ مِائَةَ دِرْهَمٍ فَقَالَ تَسْأَلُنِي مِائَةَ دِرْهَمٍ وَأَنَا ‏ ‏ابْنُ حَاتِمٍ ‏ ‏وَاللَّهِ لَا أُعْطِيكَ ثُمَّ قَالَ لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ ثُمَّ رَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلَيَأْتِ الَّذِي هُوَ خَيْرٌ ‏","","",""],[17552,17552,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا نُرْسِلُ كِلَابَنَا مُعَلَّمَاتٍ قَالَ كُلْ قَالَ قُلْتُ وَإِنْ قَتَلَ قَالَ وَإِنْ قَتَلَ مَا لَمْ يَشْرَكْهَا كِلَابٌ غَيْرُهَا قَالَ قُلْتُ فَإِنَّا نَرْمِي ‏ ‏بِمِعْرَاضٍ ‏ ‏قَالَ إِنْ ‏ ‏خَزَقَ ‏ ‏فَكُلْ وَإِنْ أَصَابَ ‏ ‏بِعَرْضِهِ ‏ ‏فَلَا تَأْكُلْ ‏","","",""],[17553,17553,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُرَيِّ بْنِ قَطَرِيٍّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّيْدِ أَصِيدُهُ قَالَ ‏ ‏أَنْهِرُوا الدَّمَ بِمَا شِئْتُمْ وَاذْكُرُوا اسْمَ اللَّهِ وَكُلُوا ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ حُذَيْفَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏يَعْنِي كُنْتُ أَسْأَلُ النَّاسَ عَنْ حَدِيثِ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏وَهُوَ إِلَى جَنْبِي لَا أَسْأَلُ عَنْهُ فَأَتَيْتُهُ فَسَأَلْتُهُ فَقَالَ نَعَمْ بُعِثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ بُعِثَ فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أُحَدِّثُ حَدِيثًا عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ فَقُلْتُ ‏ ‏هَذَا ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏فِي نَاحِيَةِ ‏ ‏الْكُوفَةِ ‏ ‏فَلَوْ أَتَيْتُهُ وَكُنْتُ أَنَا الَّذِي أَسْمَعُهُ مِنْهُ فَأَتَيْتُهُ فَقُلْتُ إِنِّي كُنْتُ أُحَدَّثُ عَنْكَ حَدِيثًا فَأَرَدْتُ أَنْ أَكُونَ أَنَا الَّذِي أَسْمَعُهُ مِنْكَ ‏ ‏قَالَ ‏ ‏لَمَّا بُعِثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَرْتُ حَتَّى كُنْتُ فِي أَقْصَى ‏ ‏الرُّومِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17554,17554,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏بَيَانٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنَّا قَوْمٌ نَتَصَيَّدُ بِهَذِهِ الْكِلَابِ قَالَ ‏ ‏إِذَا أَرْسَلْتَ كِلَابَكَ الْمُعَلَّمَةَ وَذَكَرْتَ اسْمَ اللَّهِ فَكُلْ مِمَّا أَمْسَكْنَ عَلَيْكَ وَإِنْ قَتَلَتْ إِلَّا أَنْ يَأْكُلَ الْكَلْبُ فَإِنْ أَكَلَ فَلَا تَأْكُلْ فَإِنِّي أَخَافُ أَنْ يَكُونَ إِنَّمَا أَمْسَكَ عَلَى نَفْسِهِ وَإِنْ خَالَطَهَا كِلَابٌ مِنْ غَيْرِهَا فَلَا تَأْكُلْ ‏","","",""],[17555,17555,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَعْقِلٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا النَّارَ قَالَ فَأَشَاحَ بِوَجْهِهِ حَتَّى ظَنَنَّا أَنَّهُ يَنْظُرُ إِلَيْهَا ثُمَّ قَالَ اتَّقُوا النَّارَ وَأَشَاحَ بِوَجْهِهِ قَالَ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏اتَّقُوا النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ فَإِنْ لَمْ تَجِدُوا فَبِكَلِمَةٍ طَيِّبَةٍ ‏","","",""],[17556,17556,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ الطَّائِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ ‏","","",""],[17557,17557,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْعَزِيزِ بْنَ رُفَيْعٍ ‏ ‏يُحَدِّثُ قَالَ سَمِعْتُ ‏ ‏تَمِيمَ بْنَ طَرَفَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ ثُمَّ رَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيَأْتِ الَّذِي هُوَ خَيْرٌ وَلْيَتْرُكْ يَمِينَهُ ‏","","",""],[17558,17558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏اتَّقُوا النَّارَ وَاعْمَلُوا خَيْرًا وَافْعَلُوا فَإِنِّي ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَعْقِلٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَدِيَّ بْنَ حَاتِمٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اتَّقُوا النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ ‏","","",""],[17559,17559,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْجُوَيْرِيَةِ ‏ ‏عَنْ ‏ ‏مَعْنِ بْنِ يَزِيدَ السُّلَمِيِّ ‏ ‏سَمِعْتُهُ يَقُولُ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا وَأَبِي وَجَدِّي وَخَاصَمْتُ إِلَيْهِ ‏ ‏فَأَفْلَجَنِي ‏ ‏وَخَطَبَ عَلَيَّ فَأَنْكَحَنِي ‏","","",""],[17560,17560,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ حَاطِبٍ ‏ ‏قَالَ ‏ ‏تَنَاوَلْتُ قِدْرًا لِأُمِّي فَاحْتَرَقَتْ يَدِي فَذَهَبَتْ بِي أُمِّي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ يَمْسَحُ يَدِي وَلَا أَدْرِي مَا يَقُولُ أَنَا أَصْغَرُ مِنْ ذَاكَ فَسَأَلْتُ ‏ ‏أُمِّي ‏ ‏فَقَالَتْ كَانَ يَقُولُ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ وَاشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ ‏","","",""],[17561,17561,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَإِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ حَاطِبٍ ‏ ‏قَالَ ‏ ‏دَنَوْتُ إِلَى قِدْرٍ لَنَا فَاحْتَرَقَتْ يَدِي ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏أَوْ قَالَ فَوَرِمَتْ ‏ ‏قَالَ فَذَهَبَتْ بِي أُمِّي إِلَى رَجُلٍ فَجَعَلَ ‏ ‏يَتَكَلَّمُ بِكَلَامٍ لَا أَدْرِي مَا هُوَ وَجَعَلَ يَنْفُثُ فَسَأَلْتُ ‏ ‏أُمِّي ‏ ‏فِي خِلَافَةِ ‏ ‏عُثْمَانَ ‏ ‏مَنْ الرَّجُلُ فَقَالَتْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17562,17562,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏مُحَمَّدِ بْنِ حَاطِبٍ ‏ ‏فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي قَدْ ‏ ‏رَأَيْتُ أَرْضًا ذَاتَ نَخْلٍ فَاخْرُجُوا فَخَرَجَ ‏ ‏حَاطِبٌ ‏ ‏وَجَعْفَرٌ ‏ ‏فِي الْبَحْرِ قِبَلَ ‏ ‏النَّجَاشِيِّ ‏ ‏قَالَ فَوُلِدْتُ أَنَا فِي تِلْكَ السَّفِينَةِ ‏","","",""],[17563,17563,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَلْجٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ حَاطِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصْلُ مَا بَيْنَ الْحَلَالِ وَالْحَرَامِ الصَّوْتُ وَضَرْبُ الدُّفِّ ‏","","",""],[17564,17564,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِمُحَمَّدِ بْنِ حَاطِبٍ ‏ ‏إِنِّي قَدْ تَزَوَّجْتُ امْرَأَتَيْنِ لَمْ يُضْرَبْ عَلَيَّ بِدُفٍّ قَالَ بِئْسَمَا صَنَعْتَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فَصْلَ مَا بَيْنَ الْحَلَالِ وَالْحَرَامِ الصَّوْتُ ‏ ‏يَعْنِي الضَّرْبَ بِالدُّفِّ ‏","","",""],[17565,17565,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ حَاطِبٍ ‏ ‏قَالَ ‏ ‏وَقَعَتْ الْقِدْرُ عَلَى يَدِي فَاحْتَرَقَتْ يَدِي فَانْطَلَقَ بِي أَبِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ ‏ ‏يَتْفُلُ ‏ ‏فِيهَا وَيَقُولُ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ وَأَحْسِبُهُ قَالَ وَاشْفِهِ إِنَّكَ أَنْتَ الشَّافِي ‏","","",""],[17566,17566,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏دَعُوا النَّاسَ فَلْيُصِبْ بَعْضُهُمْ مِنْ بَعْضٍ فَإِذَا اسْتَنْصَحَ رَجُلٌ أَخَاهُ فَلْيَنْصَحْ لَهُ ‏","","",""],[17567,17567,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏قَالَ ‏ ‏كَانَ أَوَّلُ يَوْمٍ عَرَفْتُ فِيهِ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي لَيْلَى ‏ ‏رَأَيْتُ شَيْخًا أَبْيَضَ الرَّأْسِ وَاللِّحْيَةِ عَلَى حِمَارٍ وَهُوَ يَتْبَعُ جِنَازَةً فَسَمِعْتُهُ يَقُولُ ‏ ‏حَدَّثَنِي ‏ ‏فُلَانُ بْنُ فُلَانٍ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ ‏ ‏لِقَاءَهُ قَالَ ‏ ‏فَأَكَبَّ ‏ ‏الْقَوْمُ يَبْكُونَ فَقَالَ مَا يُبْكِيكُمْ فَقَالُوا إِنَّا نَكْرَهُ الْمَوْتَ قَالَ لَيْسَ ذَلِكَ وَلَكِنَّهُ إِذَا حَضَرَ ‏ { ‏فَأَمَّا إِنْ كَانَ مِنْ الْمُقَرَّبِينَ ‏ ‏فَرَوْحٌ ‏ ‏وَرَيْحَانٌ وَجَنَّةُ نَعِيمٍ ‏} ‏فَإِذَا بُشِّرَ بِذَلِكَ أَحَبَّ لِقَاءَ اللَّهِ وَاللَّهُ لِلِقَائِهِ أَحَبُّ ‏ { ‏وَأَمَّا إِنْ كَانَ مِنْ الْمُكَذِّبِينَ الضَّالِّينَ فَنُزُلٌ مِنْ حَمِيمٍ ‏} ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏وَفِي قِرَاءَةِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏ثُمَّ تَصْلِيَةُ جَحِيمٍ فَإِذَا بُشِّرَ بِذَلِكَ يَكْرَهُ لِقَاءَ اللَّهِ وَاللَّهُ لِلِقَائِهِ أَكْرَهُ ‏","","",""],[17568,17568,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ نُعَيْمٍ ‏ ‏قَالَ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الرَّسُولِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا دَخَلَ الْجَنَّةَ وَإِنْ زَنَى وَإِنْ سَرَقَ ‏","","",""],[17569,17569,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَامِرُ بْنُ شَهْرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خُذُوا مِنْ قَوْلِ ‏ ‏قُرَيْشٍ ‏ ‏وَدَعُوا فِعْلَهُمْ ‏","","",""],[17570,17570,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ شَهْرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خُذُوا بِقَوْلِ ‏ ‏قُرَيْشٍ ‏ ‏وَدَعُوا فِعْلَهُمْ ‏","","",""],[17571,17571,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْحَاقَ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏جُرَيٍّ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏قَالَ ‏ ‏عَقَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَدِهِ ‏ ‏أَوْ فِي يَدِي ‏ ‏فَقَالَ ‏ ‏سُبْحَانَ اللَّهِ نِصْفُ الْمِيزَانِ وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ وَاللَّهُ أَكْبَرُ تَمْلَأُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ وَالطُّهُورُ نِصْفُ الْإِيمَانِ وَالصَّوْمُ نِصْفُ الصَّبْرِ ‏","","",""],[17572,17572,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو جَبِيرَةَ بْنُ الضَّحَّاكِ ‏ ‏قَالَ ‏ ‏فِينَا نَزَلَتْ فِي ‏ ‏بَنِي سَلِمَةَ ‏ { ‏وَلَا ‏ ‏تَنَابَزُوا ‏ ‏بِالْأَلْقَابِ ‏} ‏قَالَ قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَلَيْسَ مِنَّا رَجُلٌ إِلَّا وَلَهُ اسْمَانِ أَوْ ثَلَاثَةٌ فَكَانَ إِذَا دُعِيَ أَحَدٌ مِنْهُمْ بِاسْمٍ مِنْ تِلْكَ الْأَسْمَاءِ قَالُوا يَا رَسُولَ اللَّهِ إِنَّهُ يَغْضَبُ مِنْ هَذَا قَالَ فَنَزَلَتْ ‏ { ‏وَلَا ‏ ‏تَنَابَزُوا ‏ ‏بِالْأَلْقَابِ ‏}","","",""],[17573,17573,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ الطَّائِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ سَمِعَهُ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَنْ يَهْلِكَ النَّاسُ حَتَّى ‏ ‏يُعْذِرُوا ‏ ‏مِنْ أَنْفُسِهِمْ ‏","","",""],[17574,17574,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنَّا مِنْ ‏ ‏أَشْجَعَ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيَّ خَاتَمًا مِنْ ذَهَبٍ فَأَمَرَنِي أَنْ أَطْرَحَهُ فَطَرَحْتُهُ إِلَى يَوْمِي هَذَا ‏","","",""],[17575,17575,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏لَيُغَانُ عَلَى قَلْبِي وَإِنِّي لَأَسْتَغْفِرُ اللَّهَ كُلَّ يَوْمٍ مِائَةَ مَرَّةٍ ‏","","",""],[17576,17576,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْأَغَرَّ الْمُزَنِيَّ ‏ ‏يُحَدِّثُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ يَا أَيُّهَا النَّاسُ ‏ ‏تُوبُوا إِلَى رَبِّكُمْ فَإِنِّي أَتُوبُ إِلَى اللَّهِ عَزَّ وَجَلَّ كُلَّ يَوْمٍ مِائَةَ مَرَّةٍ ‏","","",""],[17577,17577,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا أَيُّهَا النَّاسُ ‏ ‏تُوبُوا إِلَى اللَّهِ وَاسْتَغْفِرُوهُ فَإِنِّي أَتُوبُ إِلَى اللَّهِ وَأَسْتَغْفِرُهُ فِي كُلِّ يَوْمٍ مِائَةَ مَرَّةٍ فَقُلْتُ لَهُ اللَّهُمَّ إِنِّي أَسْتَغْفِرُكَ اللَّهُمَّ إِنِّي أَتُوبُ إِلَيْكَ اثْنَتَانِ أَمْ وَاحِدَةٌ فَقَالَ هُوَ ذَاكَ ‏ ‏أَوْ نَحْوَ هَذَا ‏","","",""],[17578,17578,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَيُّوبَ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ الْمَعْنَي ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏تُوبُوا إِلَى اللَّهِ وَاسْتَغْفِرُوهُ فَإِنِّي أَتُوبُ إِلَى اللَّهِ وَأَسْتَغْفِرُهُ فِي كُلِّ يَوْمٍ مِائَةَ مَرَّةٍ أَوْ أَكْثَرَ مِنْ مِائَةِ مَرَّةٍ ‏","","",""],[17579,17579,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏عَرْفَجَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَكُونُ ‏ ‏هَنَاتٌ ‏ ‏وَهَنَاتٌ ‏ ‏فَمَنْ أَرَادَ أَنْ يُفَرِّقَ أَمْرَ الْمُسْلِمِينَ وَهُمْ جَمِيعٌ فَاضْرِبُوهُ بِالسَّيْفِ كَائِنًا مَنْ كَانَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏عَرْفَجَةَ الْأَشْجَعِيِّ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ ‏ ‏وَقَالَ ‏ ‏شَيْبَانُ ‏ ‏ابْنِ شُرَيْحٍ الْأَسْلَمِيِّ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17580,17580,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عُمَارَةَ بْنِ رُوَيْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلَهُ رَجُلٌ مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏قَالَ أَخْبِرْنِي مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏يَلِجُ ‏ ‏النَّارَ أَحَدٌ صَلَّى قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ أَنْ تَغْرُبَ ‏ ‏قَالَ ‏ ‏آنْتَ سَمِعْتَهُ مِنْهُ قَالَ ‏ ‏سَمِعَتْ أُذُنَايَ وَوَعَاهُ قَلْبِي فَقَالَ الرَّجُلُ وَاللَّهِ لَقَدْ سَمِعْتُهُ يَقُولُ ذَلِكَ ‏","","",""],[17581,17581,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏الْبَخْتَرِيُّ بْنُ الْمُخْتَارِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُمَارَةَ بْنِ رُوَيْبَةَ الثَّقَفِيِّ ‏ ‏سَمِعُوهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَنْ ‏ ‏يَلِجَ ‏ ‏النَّارَ رَجُلٌ صَلَّى قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا ‏ ‏فَقَالَ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏آنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَعَمْ قَالَ أَشْهَدُ لَسَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي ‏","","",""],[17582,17582,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ رُوَيْبَةَ ‏ ‏أَنَّهُ ‏ ‏رَأَى ‏ ‏بِشْرَ بْنَ مَرْوَانَ ‏ ‏عَلَى الْمِنْبَرِ رَافِعًا يَدَيْهِ يُشِيرُ بِإِصْبَعَيْهِ يَدْعُو فَقَالَ لَعَنَ اللَّهُ هَاتَيْنِ ‏ ‏الْيُدَيَّتَيْنِ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏يَدْعُو وَهُوَ يُشِيرُ بِإِصْبَعٍ ‏","","",""],[17583,17583,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَوْ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ مُضَرِّسٍ الطَّائِيُّ ‏ ‏قَالَ ‏ ‏جِئْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَوْقِفِ فَقُلْتُ جِئْتُ يَا رَسُولَ اللَّهِ مِنْ جَبَلَيْ ‏ ‏طَيِّئٍ ‏ ‏أَكْلَلْتُ ‏ ‏مَطِيَّتِي ‏ ‏وَأَتْعَبْتُ نَفْسِي وَاللَّهِ مَا تَرَكْتُ مِنْ جَبَلٍ إِلَّا وَقَفْتُ عَلَيْهِ هَلْ لِي مِنْ حَجٍّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَدْرَكَ مَعَنَا هَذِهِ الصَّلَاةَ وَأَتَى ‏ ‏عَرَفَاتٍ ‏ ‏قَبْلَ ذَلِكَ لَيْلًا أَوْ نَهَارًا تَمَّ حَجُّهُ وَقَضَى ‏ ‏تَفَثَهُ ‏","","",""],[17584,17584,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي السَّفَرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ مُضَرِّسِ بْنِ حَارِثَةَ بْنِ لَامٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِجَمْعٍ ‏ ‏فَقُلْتُ لَهُ هَلْ لِي مِنْ حَجٍّ فَقَالَ ‏ ‏مَنْ صَلَّى مَعَنَا هَذِهِ الصَّلَاةَ فِي هَذَا الْمَكَانِ ثُمَّ وَقَفَ مَعَنَا هَذَا الْمَوْقِفَ حَتَّى ‏ ‏يُفِيضَ ‏ ‏الْإِمَامُ ‏ ‏أَفَاضَ ‏ ‏قَبْلَ ذَلِكَ مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏لَيْلًا أَوْ نَهَارًا فَقَدْ تَمَّ حَجُّهُ وَقَضَى ‏ ‏تَفَثَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُرْوَةَ بْنِ مُضَرِّسِ بْنِ أَوْسِ بْنِ حَارِثَةَ بْنِ لَامٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي السَّفَرِ ‏ ‏حَدَّثَنِي قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُضَرِّسِ بْنِ أَوْسِ بْنِ حَارِثَةَ بْنِ لَامٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِجَمْعٍ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏رَوْحٍ ‏","","",""],[17585,17585,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُرْوَةُ بْنُ مُضَرِّسٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِجَمْعٍ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ هَلْ لِي مِنْ حَجٍّ فَقَالَ ‏ ‏مَنْ صَلَّى مَعَنَا هَذِهِ الصَّلَاةَ فِي هَذَا الْمَكَانِ وَوَقَفَ مَعَنَا هَذَا الْمَوْقِفَ حَتَّى ‏ ‏يُفِيضَ ‏ ‏أَفَاضَ ‏ ‏قَبْلَ ذَلِكَ مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏لَيْلًا أَوْ نَهَارًا فَقَدْ تَمَّ حَجُّهُ وَقَضَى ‏ ‏تَفَثَهُ ‏","","",""],[17586,17586,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَآنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ وَأَنَا فِي الشَّمْسِ ‏ ‏فَأَمَرَنِي فَحَوَّلْتُ إِلَى الظِّلِّ ‏","","",""],[17587,17587,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ سَلْمَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبْرِدُوا ‏ ‏بِالظُّهْرِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[17588,17588,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْمَاعِيلَ يَعْنِي بَشِيرًا ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ صَفْوَانَ الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدُوا ‏ ‏بِصَلَاةِ الظُّهْرِ فَإِنَّ الْحَرَّ مِنْ ‏ ‏فَوْرِ ‏ ‏جَهَنَّمَ ‏","","",""],[17589,17589,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ صُرَدٍ ‏ ‏يَقُولُ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ صُرَدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْأَحْزَابِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏يَعْنِي يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏الْآنَ نَغْزُوهُمْ وَلَا ‏ ‏يَغْزُونَا ‏","","",""],[17590,17590,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ صُرَدٍ ‏ ‏قَالَ ‏ ‏انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْأَحْزَابِ قَالَ ‏ ‏الْآنَ نَغْزُوهُمْ وَلَا ‏ ‏يَغْزُونَا ‏","","",""],[17591,17591,"","","‏ ‏وَمِمَّا اجْتَمَعَ فِيهِ ‏ ‏سُلَيْمَانُ بْنُ صُرَدٍ ‏ ‏وَخَالِدُ بْنُ عُرْفُطَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏سُلَيْمَانَ بْنِ صُرَدٍ ‏ ‏وَخَالِدِ بْنِ عُرْفُطَةَ ‏ ‏وَهُمَا يُرِيدَانِ أَنْ يَتْبَعَا جِنَازَةَ ‏ ‏مَبْطُونٍ ‏ ‏فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ أَلَمْ يَقُلْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَقْتُلُهُ بَطْنُهُ فَلَنْ يُعَذَّبَ فِي قَبْرِهِ فَقَالَ بَلَى ‏","","",""],[17592,17592,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏جَامِعُ بْنُ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَسَارٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏سُلَيْمَانُ بْنُ صُرَدٍ ‏ ‏وَخَالِدُ بْنُ عُرْفُطَةَ ‏ ‏قَاعِدَيْنِ قَالَ فَذُكِرَ أَنَّ رَجُلًا مَاتَ بِالْبَطْنِ فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ أَمَا سَمِعْتَ ‏ ‏أَوَمَا بَلَغَكَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَتَلَهُ بَطْنُهُ فَلَنْ يُعَذَّبَ فِي قَبْرِهِ قَالَ الْآخَرُ بَلَى ‏","","",""],[17593,17593,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَانٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ الشَّيْبَانِيُّ أَبُو سِنَانٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏مَاتَ رَجُلٌ صَالِحٌ فَأُخْرِجَ بِجِنَازَتِهِ فَلَمَّا رَجَعْنَا تَلَقَّانَا ‏ ‏خَالِدُ بْنُ عُرْفُطَةَ ‏ ‏وَسُلَيْمَانُ بْنُ صُرَدٍ ‏ ‏وَكِلَاهُمَا قَدْ كَانَتْ لَهُ صُحْبَةٌ فَقَالَا سَبَقْتُمُونَا بِهَذَا الرَّجُلِ الصَّالِحِ فَذَكَرُوا أَنَّهُ كَانَ بِهِ بَطْنٌ وَأَنَّهُمْ خَشُوا عَلَيْهِ الْحَرَّ قَالَ فَنَظَرَ أَحَدُهُمَا إِلَى صَاحِبِهِ فَقَالَ أَمَا سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَتَلَهُ بَطْنُهُ لَمْ يُعَذَّبْ فِي قَبْرِهِ ‏","","",""],[17594,17594,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ عَبَّادٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَمَّارِ بْنِ يَاسِرٍ ‏ ‏يَا ‏ ‏أَبَا الْيَقْظَانِ ‏ ‏أَرَأَيْتَ هَذَا الْأَمْرَ الَّذِي أَتَيْتُمُوهُ بِرَأْيِكُمْ أَوْ شَيْءٌ ‏ ‏عَهِدَهُ ‏ ‏إِلَيْكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا عَهِدَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا لَمْ يَعْهَدْهُ إِلَى النَّاسِ ‏","","",""],[17595,17595,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ الْمُرَادِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَمَّارٌ ‏ ‏قَالَ ‏ ‏لَمَّا هَجَانَا الْمُشْرِكُونَ شَكَوْنَا ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏قُولُوا لَهُمْ كَمَا يَقُولُونَ لَكُمْ قَالَ فَلَقَدْ رَأَيْتُنَا نُعَلِّمُهُ ‏ ‏إِمَاءَ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏","","",""],[17596,17596,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَاجِيَةَ الْعَنَزِيِّ ‏ ‏قَالَ ‏ ‏تَدَارَأَ ‏ ‏عَمَّارٌ ‏ ‏وَعَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏فِي التَّيَمُّمِ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَوْ مَكَثْتُ شَهْرًا لَا أَجِدُ فِيهِ الْمَاءَ لَمَا صَلَّيْتُ فَقَالَ لَهُ ‏ ‏عَمَّارٌ ‏ ‏أَمَا تَذْكُرُ إِذْ كُنْتُ أَنَا وَأَنْتَ فِي الْإِبِلِ فَأَجْنَبْتُ ‏ ‏فَتَمَعَّكْتُ ‏ ‏تَمَعُّكَ ‏ ‏الدَّابَّةِ فَلَمَّا رَجَعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِالَّذِي صَنَعْتُ فَقَالَ إِنَّمَا كَانَ ‏ ‏يَكْفِيكَ التَّيَمُّمُ ‏","","",""],[17597,17597,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي غَنِيَّةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏جَدِّ أَبِيهِ ‏ ‏الْمُخَارِقِ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏عَمَّارًا ‏ ‏يَوْمَ الْجَمَلِ وَهُوَ يَبُولُ فِي ‏ ‏قَرْنٍ ‏ ‏فَقُلْتُ أُقَاتِلُ مَعَكَ فَأَكُونُ مَعَكَ قَالَ قَاتِلْ تَحْتَ رَايَةِ قَوْمِكَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَحِبُّ لِلرَّجُلِ أَنْ يُقَاتِلَ تَحْتَ ‏ ‏رَايَةِ ‏ ‏قَوْمِهِ ‏","","",""],[17598,17598,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَيْشُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبْجَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏وَاصِلِ بْنِ حَيَّانَ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو وَائِلٍ ‏ ‏خَطَبَنَا ‏ ‏عَمَّارٌ ‏ ‏فَأَبْلَغَ وَأَوْجَزَ فَلَمَّا نَزَلَ قُلْنَا يَا ‏ ‏أَبَا الْيَقْظَانِ ‏ ‏لَقَدْ أَبْلَغْتَ وَأَوْجَزْتَ فَلَوْ كُنْتَ تَنَفَّسْتَ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ طُولَ صَلَاةِ الرَّجُلِ وَقِصَرَ خُطْبَتِهِ ‏ ‏مَئِنَّةٌ ‏ ‏مِنْ فِقْهِهِ فَأَطِيلُوا الصَّلَاةَ وَأَقْصِرُوا الْخُطْبَةَ فَإِنَّ مِنْ ‏ ‏الْبَيَانِ ‏ ‏لَسِحْرًا ‏","","",""],[17599,17599,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَسَلَّمْتُ عَلَيْهِ فَرَدَّ عَلَيَّ السَّلَامَ ‏","","",""],[17600,17600,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏إِنَّهُ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ التَّيَمُّمِ فَقَالَ ‏ ‏ضَرْبَةٌ لِلْكَفَّيْنِ وَالْوَجْهِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي التَّيَمُّمِ ضَرْبَةٌ لِلْوَجْهِ وَالْكَفَّيْنِ ‏","","",""]];
